(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-agentic-vlm-pd-disagg"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-1\">一 · 事故现场：一次视觉长尾把在线解码拖进泥里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-2\">二 · 它到底解决什么：把互抢变成可传输的 KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-3\">三 · 它不解决什么：边界要提前画清楚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-4\">四 · 配比公式：分离能不能赚，取决于这道除法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-5\">五 · 一个具体例子：长尾截图请求下的两池行为</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-6\">六 · 适用边界的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-7\">七 · 拆开之后，瓶颈换了位置：分离式预填解码的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-8\">八 · 请求入池：预填池的入口分诊与视觉编码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-9\">九 · KV 出池：分页块经 NVLink 写入解码池 HBM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-10\">十 · 解码池接收：只读视觉 KV 与逐 token 自回归</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-11\">十一 · 两池各自的连续批处理与扩缩容信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-12\">十二 · 传输时延与预填节拍的对齐判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-13\">十三 · 失败模式的步骤级定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-14\">十四 · 分离式预填解码的失效边界与配比代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-15\">十五 · 端到端时延公式：三项各自的物理量纲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-16\">十六 · 整机吞吐的 min 形式与配比推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-17\">十七 · KV 传输时延小于预填节拍：掩盖条件的推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-18\">十八 · 解码池显存约束与并发上限 $\\mu$ 的推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-19\">十九 · 长尾分布下的期望时延与扩缩容触发量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-20\">二十 · 伪代码骨架与可实现的接口边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-21\">二十一 · 什么样的请求形态才配得上分离式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-22\">二十二 · 并发与批大小的两套独立刻度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-23\">二十三 · 负载不对时的三种塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-24\">二十四 · 用 SLO 反推负载配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-25\">二十五 · 边界条件与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-26\">二十六 · 负载配方与失效边界：这套拆分在什么请求形态下才成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-27\">二十七 · 硬件档位的切分原则：先分池，再谈卡型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-28\">二十八 · 并行拓扑：预填池张量并行、解码池按 KV 切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-29\">二十九 · 量化方案：预填吃 FP8/NVFP4，解码保 KV 精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-30\">三十 · KV 策略：分页块、只读标记与传输节拍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-31\">三十一 · 调度参数与可复现配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-32\">三十二 · 五条资源账：谁在抢谁</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-33\">三十三 · 传输时延必须被预填节拍掩盖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-34\">三十四 · 配比公式与它的三个失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-35\">三十五 · 块表同步：一条容易被忽略的正确性代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-36\">三十六 · 规模上去以后，先崩的是带宽账而不是算力账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-37\">三十七 · 尾延迟的真实构成与工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-38\">三十八 · 精度问题：跨池 KV 的数值一致性与块表语义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-39\">三十九 · OOM：显存被谁吃掉，以及分页块的跨池账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-40\">四十 · 批抖动与路由不均：队列深度是唯一可信信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-41\">四十一 · 尾延迟尖刺：KV 传输成为新瓶颈的识别</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-42\">四十二 · 监控面与回滚：把回滚做成一次配比切换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-43\">四十三 · 失效边界：当NVLink与配比精度成为新瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-44\">四十四 · 选型的第一性问题：谁在抢谁的资源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-45\">四十五 · 同族算法对照：五种路线各自消除什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-46\">四十六 · 决策表：按负载形态与互联条件落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-47\">四十七 · 配比与容量：选型之后的第二个决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-48\">四十八 · 边界条件与回退路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-agentic-vlm-pd-disagg-sec-49\">四十九 · 同族选型的边界判据：预填解码分离何时赢、何时被反噬</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:587px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 586.8 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"504.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入预填池，ViT编码图像并与文本拼接做一次全序列前向，产出视觉+文本…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"504.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预填池把KV按分页块经NVLink写入解码池的HBM，块表跨池同步</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"504.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码池接收KV后只做逐token自回归，视觉KV标记只读不重算</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"504.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">两池各自维护连续批处理队列，预填池按视觉token数扩缩，解码池按并发序列…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"504.8\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">监控KV传输时延与池间队列深度，动态调整两池GPU配比以匹配SLO</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-1\">一 · 事故现场：一次视觉长尾把在线解码拖进泥里</h3>\n<p>某多模态 agent 服务在 NVL72 整机上以同卡预填解码上线。请求形态是典型的 agent 负载：一部分是纯文本短问，另一部分是带高分辨率截图、PDF 页面或长视频帧序列的视觉请求，视觉 token 数分布极不均匀，长尾请求的视觉 token 量可以是中位数的十几倍。上线初期平均吞吐看起来正常，问题出在 P99 上：每当一批长尾视觉请求同时到达，ViT 编码与跨模态注意力在 SM 上铺开，HBM 带宽被预填的权重读取和激活写回占满，同卡上正在逐 token 自回归的解码序列立刻被挤到边上——解码本身是显存带宽密集但计算很轻的活，它抢不到 SM 也抢不到带宽，token 间隔被拉长，在线 SLO 直接击穿。反过来，当长尾视觉请求退潮，解码队列变短，预填的算力又大量闲置，整机吞吐掉下来。这就是同卡部署的结构性矛盾：预填是计算密集且长尾，解码是带宽密集且短，两者在同一组 SM 与同一份 HBM 带宽上互相抢占，任何批调度技巧都只是在矛盾内部做微调，无法同时把两条曲线压平。</p>\n<p>用公式看更清楚。端到端时延由三段构成：</p>\n<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{pre}}^{\\text{vis}} + \\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}} + T_{\\text{dec}},\\quad \\text{整机吞吐} = \\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$$</div>\n<p>同卡部署时，$T_{\\text{pre}}^{\\text{vis}}$ 与 $T_{\\text{dec}}$ 不是相加而是相互污染：预填占用的带宽抬高了每个解码 step 的实际耗时，解码占用的 SM 又拉长了预填的尾延迟。整机吞吐取两阶段吞吐的较小值，意味着只要一侧被另一侧拖慢，另一侧的富余算力就白费。事故的根因不是某个算子慢，而是两阶段被强行绑在同一资源池里，吞吐的短板由抢占决定而非由需求决定。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-2\">二 · 它到底解决什么：把互抢变成可传输的 KV</h3>\n<p>预填解码分离（PD 分离）针对的正是上述抢占，做法是把视觉预填与文本解码拆到不同 GPU 池。预填池承担 ViT 编码、图像与文本拼接后的一次全序列前向，产出视觉 KV 与文本 KV；解码池只做逐 token 自回归，接收 KV 后把视觉 KV 标记为只读、不再重算。两池之间用 NVLink/C2C 搬运 KV，按分页块写入解码池 HBM，块表跨池同步。这样预填的 SM 占用与解码的带宽占用在物理上被切开，$T_{\\text{pre}}^{\\text{vis}}$ 与 $T_{\\text{dec}}$ 从互相污染变成可并行叠加，整机吞吐不再被单卡抢占锁死。给出的整机结果是 NVL72 上吞吐提升 1.6–2.2 倍、解码 P99 时延下降 50%，这两个数字对应的正是“解码不再被视觉长尾拖慢”和“预填算力不再随解码空闲而闲置”两件事。</p>\n<p>它解决的第二类问题是扩缩容维度的错配。预填池按视觉 token 数扩缩，解码池按并发序列数扩缩，两个维度天然不同：视觉请求多时该加预填卡，在线会话多时该加解码卡。同卡部署无法表达这种差异化扩容，只能整机加卡，加下去的那部分算力有一半用不上。分离后两池各自维护连续批处理队列，扩容决策可以分别落到最紧的那一侧。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-3\">三 · 它不解决什么：边界要提前画清楚</h3>\n<p>PD 分离不是万能的加速器，它的收益有明确的适用边界，越过边界就会变成负收益。第一，它不解决视觉 token 本身的冗余。ViT 输出的视觉 token 数量、跨模态注意力的计算量、视觉 KV 的绝对体积，都不因分离而减少；如果视觉 token 极长，KV 体积 $S_{\\text{KV}}$ 变大，跨池传输项 $\\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}}$ 会从被掩盖的配角变成新瓶颈，预填池的算力被传输等待拖住，此时分离反而不如同卡。第二，它不解决配比失配。两池 GPU 数量需要在线调优，配比错了就是一侧空闲、另一侧排队，整机吞吐可能低于同卡部署；这需要容量规划模型支撑，而不是靠分离本身自动收敛。第三，它不解决块表同步的正确性。块表跨池同步若有延迟，解码池按过期映射 gather KV 会读到错误块或触发重算，这是分离引入的新故障面，同卡部署不存在这个问题。第四，它对 NVLink 带宽有硬依赖：只有在 NVLink 带宽充足、能把 KV 传输时延压到预填节拍以下的整机上，传输才被掩盖；跨节点、带宽受限的部署里，这一项会直接暴露在关键路径上。</p>\n<p>还有一类问题它压根不碰：量化与数值精度、视觉 token 剪枝与压缩、投机解码、视觉缓存复用，这些是别的条目负责的杠杆。PD 分离只调整两阶段的资源归属与数据流，不改变单请求的计算图，也不改变 KV 的数值表示。把它和剪枝类方法混为一谈，会误以为分离能降低视觉 KV 体积——它不能，它只是把这份体积搬到了另一块 HBM 上。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-4\">四 · 配比公式：分离能不能赚，取决于这道除法</h3>\n<p>分离的收益不是定性的，它由两池的负载配比决定。核心关系是：</p>\n<div class=\"formula\">$$N_{pre}/N_{dec} = \\frac{T_{pre}\\cdot \\lambda}{T_{dec}\\cdot \\mu}$$</div>\n<p>其中 $T_{pre}$ 为单请求预填时延、$T_{dec}$ 为单请求解码时延、$\\lambda$ 为到达率、$\\mu$ 为解码并发。这个式子说明：预填池该配多少卡，取决于到达率与单请求预填时延的乘积；解码池该配多少卡，取决于解码并发与单请求解码时延的乘积。视觉长尾请求把 $T_{pre}$ 的分布拉得很宽，$\\lambda$ 又随 agent 会话突发，分子波动远大于分母，因此配比必须在线调，静态配比在长尾场景下必然失配。工程判断是：先测出 $T_{pre}$ 的 P99 而非均值，再按 P99 配预填池，否则长尾请求会在预填队列里堆积，把分离的收益吃掉。</p>\n<p>第二个约束是传输必须被掩盖：KV 传输时延需小于预填节拍，才能让 $\\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}}$ 不落在关键路径上。预填节拍指预填池产出一批 KV 的周期，只要传输在这个周期内完成，解码池就感觉不到搬运的存在。视觉 token 极长时 $S_{\\text{KV}}$ 上升，这条不等式先被打破，表现为预填池产出 KV 后等传输、解码池等 KV 到达，两池同时低效——这是分离最典型的失败模式，也是容量规划必须显式建模的一项。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-5\">五 · 一个具体例子：长尾截图请求下的两池行为</h3>\n<p>设 agent 服务收到一批请求，其中若干条带整页截图，视觉 token 数远超中位数，另有一批纯文本会话正在解码。同卡部署下，截图请求进入预填，ViT 与跨模态注意力占满 SM，HBM 带宽被激活写回吃掉，正在解码的会话每个 token 的间隔被拉长，P99 直接超标；等截图预填结束，解码恢复，但预填期间解码池的算力被浪费，整机吞吐的短板落在解码侧。分离部署下，截图请求只进预填池，预填池按视觉 token 数扩容，把长尾消化在自己的队列里；解码池继续按并发序列数服务纯文本会话，视觉 KV 经 NVLink 按分页块写入后标记只读，解码池的 HBM 带宽只服务于自回归读取，不被预填写回污染。结果是解码 P99 不再随截图请求到达而抖动，预填池的算力也不再随解码空闲而闲置，两池吞吐各自贴近自己的需求曲线，整机吞吐取 min 后抬升。</p>\n<p>代价同时出现：这批截图的视觉 KV 体积大，跨池传输占用 NVLink 带宽，若同一时刻还有大量解码池的 KV 读取走同一条链路，传输与解码的带宽需求会在 NVLink 上叠加。工程上要监控 KV 传输时延与池间队列深度，把配比调整建立在实测的传输时延分布上，而不是只看 GPU 利用率。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-6\">六 · 适用边界的工程判据</h3>\n<p>判断一个多模态 agent 服务该不该上 PD 分离，看三条：其一，预填长尾是否明显——视觉 token 数分布是否足够宽，宽到同卡部署下解码 P99 被预填拖动的幅度超过可接受阈值；其二，NVLink 带宽是否充足——KV 传输时延能否稳定压在预填节拍以下，视觉 KV 体积最大的那批请求是否仍在链路能力之内；其三，是否有在线容量规划能力——能否按 $N_{pre}/N_{dec}$ 的式子持续调优，并在块表同步上做到不读到过期映射。三条同时满足，分离的 1.6–2.2 倍吞吐与 50% P99 下降才落得下来；缺一条，失败模式就会先于收益出现：传输成瓶颈、配比失配、块表过期，三者任一都会把整机吞吐拉回同卡水平甚至更低。规模上限由 KV 传输带宽与配比调优精度共同约束，这两项不是部署后能靠加卡解决的，必须在容量规划阶段就写进模型。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-7\">七 · 拆开之后，瓶颈换了位置：分离式预填解码的失效边界</h3>\n\n<p>先说一个线上事故的形态，而不是它的数字。某多模态 agent 服务在单卡同池部署下，白天时段整机吞吐始终上不去：视觉预填的长尾请求（一张高分辨率截图、一页 PDF 扫描件）一旦进入批，ViT 与跨模态注意力的全序列前向会长时间占满 SM 并持续吃 HBM 带宽，正在逐 token 自回归的会话被挤到调度队列尾部，解码 P99 时延被拉长；反过来，当预填队列空而解码队列满时，解码只做带宽密集的短步进，SM 大量闲置，预填算力白白浪费。团队按“拆池”思路把视觉预填与文本解码分到不同 GPU 池，KV 经 NVLink 搬运，整机吞吐拿到 1.6–2.2 倍提升、解码 P99 下降 50%。但事故恰恰发生在拆分之后：一批视觉 token 极长的请求涌入，预填池的算力被 KV 传输等待拖住，解码池却在等块表，整机吞吐反而低于同卡部署。这说明分离式方案不是无条件更优，它的收益被一条传输不等式锁死。</p>\n\n<p>这条不等式是本方案的真正适用边界。KV 跨池搬运必须被预填节拍掩盖，否则预填池产出的速度受限于 NVLink 而非 SM：</p>\n\n<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{pre}}^{\\text{vis}} + \\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}} + T_{\\text{dec}},\\quad \\text{整机吞吐} = \\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$$</div>\n\n<p>式中 $S_{\\text{KV}}$ 是单请求视觉加文本 KV 的字节数，随视觉 token 数线性增长。当视觉 token 数把 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 推到与 $T_{\\text{pre}}^{\\text{vis}}$ 同量级时，传输项不再是可掩盖的尾巴，而成为端到端时延的主项；此时整机吞吐由 $\\min$ 里较小的那一侧决定，而预填池因等待传输而空转，两侧同时不满载。这就是“拆开之后瓶颈换位置”的机理：同卡部署的瓶颈是 SM 与 HBM 互抢，分离式部署的瓶颈是 NVLink 带宽与块表同步。前者可用拆池消除，后者只能靠带宽余量与配比精度缓解。</p>\n\n<p>配比失配是第二个失效条件，且比带宽更容易被忽视。两池独立扩缩容的前提是配比跟得上负载配方，稳态下应满足</p>\n\n<div class=\"formula\">$$N_{pre}/N_{dec} = \\frac{T_{pre}\\cdot \\lambda}{T_{dec}\\cdot \\mu}$$</div>\n\n<p>其中 $\\lambda$ 为到达率、$\\mu$ 为解码并发。agent 负载的到达率与视觉 token 分布都是长尾且突发的，$T_{pre}$ 随图像分辨率漂移，靠静态配比必然在一侧堆积、另一侧空闲。缺少在线容量规划模型时，运维只能按经验调池，结果是整机吞吐低于同卡部署——这正是事故的第二段。第三个失效点是块表跨池同步：解码池按分页块 gather KV，若块表同步滞后于 KV 落盘，解码侧会按过期映射读到错误块，或保守地触发重算，把已经付过的预填算力再付一遍。工程上应把块表同步做成与 KV 写入同一条 NVLink 事务链上的有序发布，而非两条独立通道。</p>\n\n<table class=\"mini\"><thead><tr><th>条件</th><th>分离式收益</th><th>失效表现</th></tr></thead><tbody><tr><td>视觉预填长尾明显、NVLink 余量充足</td><td>吞吐 1.6–2.2 倍，解码 P99 降 50%</td><td>—</td></tr><tr><td>视觉 token 极长，$S_{\\text{KV}}/BW$ 逼近 $T_{\\text{pre}}^{\\text{vis}}$</td><td>收益被传输吃掉</td><td>预填池等传输，吞吐受 NVLink 限</td></tr><tr><td>配比失配、无在线容量模型</td><td>—</td><td>一侧空闲一侧排队，吞吐低于同卡</td></tr><tr><td>块表同步滞后</td><td>—</td><td>读到错误块或触发重算</td></tr></tbody></table>\n\n<p>由此可给出本方案的适用判断：它解决的是“预填与解码在同一 GPU 上互抢 SM 与 HBM 带宽”这一类问题，适用于预填长尾显著、NVLink 带宽有富余的 NVL72 整机；它不解决单请求内的算力瓶颈，也不解决视觉编码本身的算子效率，更不适用于视觉 token 规模已使 KV 传输成为主项的负载。规模上限由 KV 传输带宽与配比调优精度共同约束，落地前应先测出本负载的 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 与 $T_{\\text{pre}}^{\\text{vis}}$ 之比，再决定是否拆池。</p>\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-8\">八 · 请求入池：预填池的入口分诊与视觉编码</h3>\n<p>请求进入预填池的第一件事不是立刻跑 ViT，而是分诊：调度器读取请求里的图像数量、分辨率、文本长度，估算视觉 token 数 $n_{\\text{vis}}$ 与总序列长度 $S$，据此决定它进哪个连续批处理批次。输入是原始请求（图像张量 + 提示词），输出是一条被赋予预填预算的队列条目。代价在这一步就已经可见：视觉 token 数是后续所有扩缩容决策的锚，预填池按视觉 token 数扩缩而非按请求数扩缩，正是因为一条 4K 图像请求的 ViT 前向可能顶得上几十条纯文本请求的算力。</p>\n<p>随后 ViT 编码图像，patch embedding 与多层注意力把像素变成视觉 token 序列，再与文本 token 拼接，做一次全序列前向。这一次前向同时产出视觉 KV 与文本 KV，注意跨模态注意力层里视觉 token 作为 key/value 被文本 query 读取，因此视觉 KV 在这一步就被完整物化，而不是留给解码池重算。输入是图像与拼接后的 token 序列，输出是分页化的 KV 块集合加上一份块表。代价集中在 SM 占用与 HBM 写入：ViT 是计算密集段，跨模态注意力是 $O(n_{\\text{vis}} \\cdot n_{\\text{txt}})$ 的注意力开销，两者叠加使预填池的 SM 利用率长期贴顶，而 HBM 带宽在这一步只承担 KV 写回，压力远小于解码池。</p>\n<p>具体例子：一条 agent 请求携带两张 1024×1024 截图与一段工具调用说明，ViT 产出数百个视觉 token，拼接后全序列前向一次算完，KV 按固定页大小切块写入预填池本地 HBM。此时预填池的批处理队列按视觉 token 总数装箱，而不是按请求条数装箱——这是与同卡部署最直接的分歧点，同卡部署里这条请求会和正在解码的序列抢同一批 SM。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-9\">九 · KV 出池：分页块经 NVLink 写入解码池 HBM</h3>\n<p>预填完成后，KV 不留在原地等解码，而是按分页块经 NVLink 写入解码池的 HBM。输入是预填池本地 HBM 中的 KV 块与块表，输出是解码池 HBM 中同一逻辑块的副本，以及跨池同步后的块表映射。传输以块为单位流水推进，块表在两侧保持一致，解码池拿到块表就知道每个逻辑页落在本地哪块物理显存。这一步的代价是 NVLink 带宽占用与传输时延：</p>\n<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{pre}}^{\\text{vis}} + \\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}} + T_{\\text{dec}}$$</div>\n<p>公式把端到端时延拆成三段，中间项就是 KV 搬运。工程判断的关键在于这一项必须被预填节拍掩盖：只要单次 KV 传输时延小于预填池产出一个批次的节拍，传输就和下一批预填重叠，不进入关键路径。NVL72 的 NVLink 高带宽正是为此存在——它让 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 在常规视觉 token 规模下小到可以忽略，从而把两池解耦的收益兑现。</p>\n<p>但这一项不是恒定的。视觉 token 极长时 $S_{\\text{KV}}$ 线性膨胀，传输时延超过预填节拍，预填池的算力就被传输等待拖住：SM 算完了却发不出去，下一批进不来。这就是该机制的第一个失败模式，也是规模上限的来源。具体例子：一条请求带十几张高分辨率图，视觉 KV 体量远超常规，块传输占满 NVLink 通道，预填池队列深度上升而解码池仍在等 KV，两池同时出现空闲与排队并存的错配。工程上此时的应对不是加大批，而是把该请求的视觉 token 预算纳入分诊，或让传输与预填以更细的块粒度交错。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-10\">十 · 解码池接收：只读视觉 KV 与逐 token 自回归</h3>\n<p>解码池收到 KV 后的动作被严格限定：逐 token 自回归，视觉 KV 标记为只读，永不重算。输入是同步好的块表、已落地的 KV 块与当前 token，输出是下一个 token 及其追加的文本 KV。视觉 KV 只读这一约束是整条流水线的经济性来源——解码池的 HBM 带宽全部用于读取 KV 与写新 token 的 KV，不被 ViT 或跨模态注意力分走一个 SM。解码是显存带宽密集且短的段，其单请求时延 $T_{\\text{dec}}$ 主要由 KV 读取量除以有效带宽决定，与视觉 token 数弱相关（视觉 KV 只读一次进注意力），与并发序列数强相关。</p>\n<p>代价在这里体现为解码池的 HBM 带宽压力与批内序列数上限。连续批处理队列按并发序列数装箱，每条序列每步只追加一个 token 的 KV，增量写很小，但读的是整条历史 KV，因此批越大单位 token 摊到的带宽成本越低。具体例子：解码池同时服务数十条 agent 会话，每条会话的视觉 KV 已在 HBM 中就位，每步自回归只做一次全历史注意力读取加一次增量写，视觉部分不触发任何重算——这与同卡部署中解码步被预填抢占 SM 导致 P99 抖动的形态形成对照，也是解码 P99 时延下降 50% 的机制来源。</p>\n<p>块表跨池同步若滞后，解码池按过期映射 gather KV 会读到错误块或触发重算，这是第二个失败模式：它不是性能问题而是正确性问题，工程上要求块表同步与块数据传输走同一条有序通道，或在解码池侧做块版本校验。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-11\">十一 · 两池各自的连续批处理与扩缩容信号</h3>\n<p>两池各自维护独立的连续批处理队列，扩缩容信号不同源。预填池按视觉 token 数扩缩：队列里待处理的视觉 token 总量除以单卡每秒可处理的视觉 token 吞吐，得到所需 GPU 数。解码池按并发序列数扩缩：活跃序列数乘以每序列每步的 KV 读取量，除以单卡 HBM 带宽可得下界。输入是各自的队列深度与在飞请求，输出是 GPU 配比调整指令。代价是配比失配时的整机吞吐塌陷——一侧空闲另一侧排队，整机吞吐被短板卡住：</p>\n<div class=\"formula\">$$\\text{整机吞吐} = \\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$$</div>\n<p>这个 min 是分离式部署的硬约束，也是配比公式的由来：</p>\n<div class=\"formula\">$$N_{pre}/N_{dec} = \\frac{T_{pre}\\cdot \\lambda}{T_{dec}\\cdot \\mu}$$</div>\n<p>其中 $\\lambda$ 为到达率、$\\mu$ 为解码并发，$T_{pre}$ 与 $T_{dec}$ 分别是单请求预填与解码时延。公式的含义是：预填侧需要的算力与到达率和单请求预填时延成正比，解码侧需要的算力与解码并发和单请求解码时延成正比，两侧配比必须让两条流水线的吞吐相等，否则 min 取到短板。具体例子：agent 长尾视觉请求突增时 $\\lambda$ 与 $T_{pre}$ 同时上升，若配比不调，预填池排队而解码池空转，整机吞吐低于同卡部署；监控 KV 传输时延与池间队列深度并动态调参，才能把配比拉回平衡点。这一步的代价是调优本身的在线开销与容量规划模型的依赖。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-12\">十二 · 传输时延与预填节拍的对齐判据</h3>\n<p>把上述步骤串起来看，整条流水线是否成立只取决于一个判据：KV 传输时延是否小于预填节拍。预填节拍是预填池产出一个批次的时间，约等于批内视觉 token 总量除以预填吞吐；传输时延是 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 加上块表同步与协议开销。输入是批大小与视觉 token 分布，输出是一个布尔判断：掩盖成立则两池真正解耦，掩盖不成立则传输成为新瓶颈。代价以 NVLink 带宽占用计，且这部分带宽与池内通信、其他租户流量共享，视觉 token 极长时它是第一个被耗尽的资源。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>入池分诊</td><td>图像、文本、分辨率</td><td>视觉 token 预算与批次</td><td>调度开销，决定后续扩缩容锚点</td></tr>\n<tr><td>ViT + 全序列前向</td><td>像素、拼接 token</td><td>视觉+文本 KV 块</td><td>SM 计算密集，跨模态注意力 $O(n_{\\text{vis}}n_{\\text{txt}})$</td></tr>\n<tr><td>KV 跨池传输</td><td>本地 KV 块、块表</td><td>解码池 HBM 副本、同步块表</td><td>NVLink 带宽与传输时延</td></tr>\n<tr><td>解码自回归</td><td>块表、只读视觉 KV</td><td>逐 token 输出、增量文本 KV</td><td>HBM 带宽密集，批内序列数受限</td></tr>\n<tr><td>配比调整</td><td>队列深度、传输时延</td><td>两池 GPU 数</td><td>调优开销，失配则 min 取短板</td></tr>\n</tbody></table>\n<p>具体例子：一个 NVL72 整机里预填池与解码池分属不同 GPU 组，监控面同时看 KV 传输时延与两侧队列深度，当传输时延逼近预填节拍时，调度器要么缩小预填批以缩短节拍，要么把长视觉请求排到低峰，避免传输项进入关键路径。整机吞吐提升 1.6–2.2 倍的前提正是这条判据在绝大多数请求上成立。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-13\">十三 · 失败模式的步骤级定位</h3>\n<p>三个失败模式都能定位到具体步骤。传输瓶颈落在第二步：$S_{\\text{KV}}$ 膨胀使 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 超过预填节拍，预填池算力被发送等待占用，表现为预填队列深度上升而解码池 HBM 写入空闲。配比失配落在第四步：$N_{pre}/N_{dec}$ 偏离公式给出的平衡点，min 取到短板，整机吞吐低于同卡部署，表现为一侧 GPU 利用率贴顶另一侧长期低位。块表同步滞后落在第三步与第三步到第四步的衔接：解码池按过期映射 gather，读到错误块或触发视觉 KV 重算，后者直接把只读约束打破，把解码池拖回计算密集态。</p>\n<p>工程判断上，这三个模式共享同一个监控面：KV 传输时延、池间队列深度、块表版本一致性。前两个是性能信号，第三个是正确性信号，必须分开告警。容量规划模型的作用是把 $\\lambda$、$\\mu$、$T_{pre}$、$T_{dec}$ 的在线估计喂给配比公式，让第四步的调整先于队列深度恶化发生，而不是等 min 已经取到短板再补救。视觉 token 极长的请求应在分诊阶段就被标记，走独立的传输通道或降级路径，避免其 KV 体量把整条流水线的节拍判据推翻。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-14\">十四 · 分离式预填解码的失效边界与配比代价</h3>\n<p>这套池化方案不是无条件收益。它的收益成立的前提是 KV 传输时延能被预填节拍掩盖，即传输时延小于预填池产出下一批 KV 的间隔。一旦视觉 token 极长，单请求产出的视觉 KV 体量膨胀，跨池写入解码池 HBM 的时间超过预填节拍，预填池的算力就被传输等待拖住——SM 空转、NVLink 满载，原本被消除的互抢以另一种形式回归。此时整机吞吐由传输带宽而非算力决定，公式中的 <span class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{pre}}^{\\text{vis}} + \\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}} + T_{\\text{dec}}$$</span> 里中间项不再可忽略，分离式部署的端到端时延反而劣于同卡部署。适用边界因此很明确：预填长尾明显、NVLink 带宽充足的 NVL72 整机；规模上限受 KV 传输带宽与配比调优精度双重约束。</p>\n<p>配比失配是第二个失效面。两池独立扩缩容意味着 <span class=\"formula\">$$N_{pre}/N_{dec} = \\frac{T_{pre}\\cdot \\lambda}{T_{dec}\\cdot \\mu}$$</span> 必须在线维持，其中到达率 λ 与解码并发 μ 在 agent 长尾流量下剧烈波动。配比偏高时解码池排队、预填池空闲；配比偏低时预填池积压、解码池等 KV。两种失配都让整机吞吐跌到 min(Thr_pre, Thr_dec) 的短板一侧，甚至低于同卡部署——因为同卡部署至少能靠时间片复用把空闲算力捡回来。缺少在线容量规划模型时，运维只能靠监控池间队列深度事后纠偏，纠偏滞后于流量变化。</p>\n<p>第三个失效面在块表同步。解码池按分页块 gather KV 依赖跨池块表一致；块表同步若滞后于 KV 写入，解码池会按过期映射读到错误块，轻则输出错乱，重则触发视觉 KV 重算，把只读不重算的优化直接作废。工程上必须把块表更新与 KV 写入做成同一事务边界，或在解码侧加版本校验。代价上，这套方案用 NVLink 带宽换 SM 与 HBM 带宽的解耦，用在线调优复杂度换 P99 时延下降 50% 与整机吞吐 1.6–2.2 倍——收益真实，但每一条都挂在“传输可掩盖、配比可维持、块表可一致”三个前提上，任一破裂即退回同卡部署的基线。</p>\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-15\">十五 · 端到端时延公式：三项各自的物理量纲</h3>\n<p>把 <span class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{pre}}^{\\text{vis}} + \\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}} + T_{\\text{dec}}$$</span> 逐项拆开，每一项对应一个可独立测量的硬件资源。$T_{\\text{pre}}^{\\text{vis}}$ 是预填池里 ViT 编码加跨模态注意力那一次全序列前向的墙钟时间，它的量纲由视觉 token 数 $n_v$、文本 token 数 $n_t$ 与预填池单卡有效算力 $F_{\\text{pre}}$ 决定，近似写成 $T_{\\text{pre}}^{\\text{vis}} \\approx (n_v \\cdot c_v + n_t \\cdot c_t)/F_{\\text{pre}}$，其中 $c_v$、$c_t$ 是每 token 摊到的浮点运算量——视觉 token 因为要过跨模态注意力，$c_v$ 显著高于 $c_t$，这正是长尾的来源：一张高分辨率图切出的视觉 token 数可以比同请求的文本 token 高一个量级，$T_{\\text{pre}}^{\\text{vis}}$ 随之线性膨胀。</p>\n<p>第二项 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 是跨池 KV 搬运时间。$S_{\\text{KV}}$ 不是整段 KV 的字节数，而是本请求实际要写进解码池的那部分分页块字节数，按 $S_{\\text{KV}} = 2 \\cdot L \\cdot h_{kv} \\cdot d \\cdot b \\cdot (n_v + n_t)$ 估算，$L$ 为层数、$h_{kv}$ 为 KV 头数、$d$ 为头维、$b$ 为每元素字节数（FP8 下为 1，NVFP4 下更小），系数 2 表示 K 与 V 各一份。这一项的关键在于它必须被“掩盖”：只要 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 小于预填池的产出节拍，传输就落在预填池下一次发射的间隙里，不进入关键路径；一旦视觉 token 极长使 $S_{\\text{KV}}$ 抬升，这一项就从隐藏项变成瓶颈项，预填池的算力被传输等待拖住，这是该机制最典型的失败模式。</p>\n<p>第三项 $T_{\\text{dec}}$ 是解码池的逐 token 自回归时间，量纲由显存带宽而非算力决定：每步要读全部权重加全部 KV，$T_{\\text{dec}} \\approx (W + S_{\\text{KV}}^{\\text{read}})/BW_{\\text{HBM}}$，$W$ 为权重字节。视觉 KV 在解码池被标记为只读不重算，意味着它每步都被读一遍却从不被改写，这使 $S_{\\text{KV}}^{\\text{read}}$ 成为解码步的固定税。三项相加的工程含义是：分离式部署把第一项与第三项放到不同物理资源上并行，端到端时延不再等于二者之和的最大值，而等于预填池排队加传输加解码池排队——公式写的是单请求无排队的情形，真实系统要在每一项外面再套一层队列等待。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-16\">十六 · 整机吞吐的 min 形式与配比推导</h3>\n<p><span class=\"formula\">$$\\text{整机吞吐} = \\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$$</span> 这条式子不是近似，而是串联系统的硬约束：预填池产出的 KV 必须被解码池消费，任一池的稳态速率更低者决定整机吞吐。$\\text{Thr}_{\\text{pre}} = N_{\\text{pre}} \\cdot \\eta_{\\text{pre}} / T_{\\text{pre}}$，$N_{\\text{pre}}$ 为预填池 GPU 数、$\\eta_{\\text{pre}}$ 为预填池连续批处理的打包效率（受视觉 token 长度方差拖累，长尾请求会把 batch 撑到显存上限而降低 $\\eta_{\\text{pre}}$）；$\\text{Thr}_{\\text{dec}} = N_{\\text{dec}} \\cdot \\mu / T_{\\text{dec}}$，$\\mu$ 为解码池单卡可容纳的并发序列数，由 KV 显存占用决定。min 形式直接给出容量规划的目标：让两池速率相等，任何一侧过剩都是浪费。</p>\n<p>令两式相等并解出配比，就得到 <span class=\"formula\">$$N_{\\text{pre}}/N_{\\text{dec}} = \\frac{T_{\\text{pre}}\\cdot \\lambda}{T_{\\text{dec}}\\cdot \\mu}$$</span>。推导的关键一步是把到达率 $\\lambda$ 显式写进预填侧：预填池的负载不是由并发数决定，而是由单位时间到达的视觉 token 总量决定，$\\lambda$ 在这里应理解为“每秒到达请求数 × 每请求视觉 token 数”归一化后的等效到达强度；解码侧的 $\\mu$ 则是显存约束下的并发上限，二者量纲对齐后比值才有意义。这个式子的实用价值在于它把“配比”从拍脑袋变成可观测量的函数：$T_{\\text{pre}}$、$T_{\\text{dec}}$ 可从两池的批处理统计里直接读出，$\\lambda$ 从入口队列深度变化率估计，$\\mu$ 由 KV 显存水位反推。</p>\n<p>代价落在配比失配上：$N_{\\text{pre}}/N_{\\text{dec}}$ 偏大时解码池排队、预填池空闲，整机吞吐被 $\\text{Thr}_{\\text{dec}}$ 卡住；偏小时预填池排队，长尾视觉请求在预填队列里堆积，解码池等 KV 等到空闲，吞吐被 $\\text{Thr}_{\\text{pre}}$ 卡住。两种失配都使整机吞吐低于同卡部署的理论上限，且失配方向随 agent 负载的视觉 token 分布漂移而反转，所以配比必须在线调。举例：一批请求的视觉 token 数从常规量级跳到极长量级，$T_{\\text{pre}}$ 抬升数倍，原配比立刻偏向预填不足，此时若不把 GPU 从解码池划给预填池，min 的取值就锁死在 $\\text{Thr}_{\\text{pre}}$ 上。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-17\">十七 · KV 传输时延小于预填节拍：掩盖条件的推导</h3>\n<p>“KV 传输时延需小于预填节拍以被 NVLink 带宽掩盖”这句话可以写成不等式 <span class=\"formula\">$$\\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}} &lt; \\frac{T_{\\text{pre}}^{\\text{vis}}}{B_{\\text{pre}}}$$</span>，右侧 $B_{\\text{pre}}$ 是预填池的批大小，$T_{\\text{pre}}^{\\text{vis}}/B_{\\text{pre}}$ 即预填池每产出一个请求 KV 的平均节拍。把 $S_{\\text{KV}}$ 的表达式代入，不等式两边同除视觉 token 数，得到一个与请求规模无关的判据：每 token 的 KV 字节数乘以批大小，必须小于 NVLink 带宽乘以单请求预填时间。这个判据说明掩盖能力不是常数，它随 $B_{\\text{pre}}$ 增大而恶化——批越大，单位时间内要搬的 KV 越多，传输越容易从隐藏项翻成瓶颈项。</p>\n<p>推导的关键一步是把“传输”与“计算”放在同一时间轴上比较占用率：预填池在算第 $k$ 批时，NVLink 在搬第 $k-1$ 批的 KV，只要搬运时间不超过计算时间，链路占用率就低于 1，传输不进关键路径。这要求块表跨池同步与 KV 写入流水化：预填池每算完一层就按分页块发射一次写，而不是等整段 KV 算完再一次性传，否则传输被串行化到计算之后，掩盖条件自动失效。伪代码落到可实现层面，预填侧的主循环是：对每个请求做 ViT 前向与跨模态注意力，逐层把 K/V 按页写入本地暂存，页写满即发起 NVLink 写并携带块表条目；解码侧的主循环是：从跨池块表 gather 页地址，按页读 KV 进 HBM，然后只跑自回归的注意力与 FFN，视觉页标记只读。</p>\n<p>系统代价在这里体现为带宽竞争：NVLink 在 NVL72 里同时承载池间 KV 传输与张量并行的集合通信，KV 搬运占用率上升会挤压后者的可用带宽，使解码步的通信等待变长。工程判断是给 KV 传输设一个占用率上限，超过就把预填池的批大小压下来，用更小的 $B_{\\text{pre}}$ 换更短的节拍，代价是预填池的 $\\eta_{\\text{pre}}$ 下降、$\\text{Thr}_{\\text{pre}}$ 变低——这又回到 min 形式，需要与配比一起调。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-18\">十八 · 解码池显存约束与并发上限 $\\mu$ 的推导</h3>\n<p>$\\mu$ 不是配置项而是推导量：解码池单卡 HBM 容量 $M$ 减去权重占用 $W$ 与运行时开销后，剩余空间除以每序列 KV 字节数，即 <span class=\"formula\">$$\\mu = \\left\\lfloor \\frac{M - W - M_{\\text{act}}}{S_{\\text{KV}}^{\\text{seq}}} \\right\\rfloor$$</span>，$S_{\\text{KV}}^{\\text{seq}}$ 是单序列视觉加文本 KV 的总字节。视觉 KV 只读不重算的好处正在这里：它一旦写入就固定占用，不会因解码步增长而膨胀，使 $\\mu$ 在序列生命周期内可预测；代价是长视觉请求的单序列 KV 远大于纯文本请求，$\\mu$ 被少数长请求拉低，解码池的有效并发下降，$\\text{Thr}_{\\text{dec}}$ 随之下降。</p>\n<p>把 $\\mu$ 代回配比公式，可以看到一个反直觉的耦合：视觉 token 越长，$T_{\\text{pre}}$ 越大（分子变大，配比偏向更多预填卡），同时 $S_{\\text{KV}}^{\\text{seq}}$ 越大使 $\\mu$ 越小（分母变小，配比同样偏向更多预填卡），两个效应同向叠加，配比需求被放大得比线性更快。这就是为什么 agent 长尾负载下固定配比必然失配。伪代码层面，解码池的准入控制要按 $S_{\\text{KV}}^{\\text{seq}}$ 做分页预留而不是按请求数计数：新请求到达时先查剩余页数是否够放下它的视觉 KV 加一段文本 KV 的增长余量，不够就排队，避免解码中途因显存不足触发重算或换出。</p>\n<p>代价是显存碎片与页表开销：分页块跨池同步意味着解码池的块表要同时记录本地页与远端来源页，块表本身占用显存并增加 gather 时的间接寻址延迟。失败模式很具体：块表跨池同步若延迟，解码池按过期映射 gather KV 会读到错误块或触发重算，重算把已省的预填算力又花一遍，整机吞吐反而低于同卡部署。工程上给块表同步设版本号与超时，超时即拒绝该请求进解码池而不是冒险读旧映射。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-19\">十九 · 长尾分布下的期望时延与扩缩容触发量</h3>\n<p>agent 负载的视觉 token 数不是常数而是分布，端到端时延的期望要对分布取积分：<span class=\"formula\">$$\\mathbb{E}[T_{\\text{e2e}}] = \\int \\left( T_{\\text{pre}}^{\\text{vis}}(n_v) + \\frac{S_{\\text{KV}}(n_v)}{BW_{\\text{NVLink}}} + T_{\\text{dec}}(n_v) \\right) f(n_v)\\, dn_v$$</span>，$f(n_v)$ 是视觉 token 数的概率密度。推导的关键一步是注意到三项对 $n_v$ 的敏感度不同：第一项线性增长且斜率由 $c_v/F_{\\text{pre}}$ 给出，第二项线性增长且斜率由每 token KV 字节除以带宽给出，第三项只通过 $S_{\\text{KV}}^{\\text{read}}$ 缓慢增长。因此在 $n_v$ 的尾部，第一、二项主导，时延的长尾几乎完全由预填与传输决定，这正是把预填拆出去能压 P99 的原因——解码池不再被长尾预填抢占，其 P99 只受自身并发与显存约束。</p>\n<p>扩缩容触发量由此可写：预填池按“待处理视觉 token 总量 / 单卡每秒可处理视觉 token 数”扩，解码池按“活跃序列数 / $\\mu$”扩。前者用 token 计量而非请求计量，因为长尾请求的 token 数差异巨大，按请求数扩容会在长尾到来时严重不足；后者用序列计量，因为解码成本由并发序列的 KV 读取主导。两个触发量各自独立，正是两池独立扩缩容的物理基础。代价是扩缩容本身的滞后：GPU 池配比调整需要时间，滞后期间到达的长尾请求只能排队，队列深度监控因此成为配比调整的前置信号而不是事后指标。</p>\n<p>举例说明这条链：入口队列深度在短时间内抬升且抬升部分集中在高视觉 token 请求，说明 $\\lambda$ 的等效强度上升而 $T_{\\text{pre}}$ 也在上升，配比公式的分子被双重放大，此时应先把 GPU 从解码池划向预填池；若抬升的是并发序列数而视觉 token 分布不变，则 $\\mu$ 是约束，应向解码池划 GPU。两种信号必须分开看，混在一起调就会在两侧之间来回震荡。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-20\">二十 · 伪代码骨架与可实现的接口边界</h3>\n<p>把上述推导落到两个可独立部署的进程，接口只有三样东西：分页 KV 写请求、块表条目、完成信号。预填侧伪代码思路是：取批、跑 ViT 与跨模态注意力、逐层按页写本地 KV、页满即发 NVLink 写并附块表条目、整批完成发完成信号；解码侧是：收块表条目、按页 gather 进 HBM、标记视觉页只读、进连续批处理队列跑自回归、序列结束释放页。两侧队列各自独立，预填侧队列按视觉 token 数排序以稳定 $\\eta_{\\text{pre}}$，解码侧队列按剩余页数准入以稳定 $\\mu$。</p>\n<p>接口边界上要防的三件事对应三个失败模式：其一，写请求必须带页版本，解码侧 gather 前校验版本，防过期映射读错块；其二，NVLink 写必须可被限流，占用率超阈值时预填侧压批，防传输翻成瓶颈；其三，完成信号与块表条目要原子发布，防解码侧看到条目却读不到数据。这三条不涉及任何新硬件能力，只用 Blackwell 的 NVLink 高带宽与分页块表即可实现，量化与并行拓扑细节不在本片段范围内。</p>\n<p>最后落在工程判断上：这套公式体系的可用性取决于三个可观测量能否被低开销地采到——预填池的单请求预填时延、解码池的并发上限 $\\mu$、KV 传输的链路占用率。三者都可从批处理统计与页表计数里直接读出，不需要额外探针；采不到这三个量，配比公式就退化成静态配置，而静态配置在 agent 长尾负载下必然失配，整机吞吐会掉到同卡部署以下。因此这套机制的第一行代码不是拆分池，而是把这三个量做成可观测指标并接入配比调整回路。</p>\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-21\">二十一 · 什么样的请求形态才配得上分离式</h3>\n<p>分离式预填/解码不是普适架构，它是一份负载契约：只有当请求的预填成本与解码成本在时间尺度上明显不对称、且预填侧存在长尾时，拆池才换来净收益。判断依据落在两个量上——单请求预填时延 $T_{pre}$ 与单请求解码时延 $T_{dec}$ 的比值，以及到达率 $\\lambda$ 与解码并发 $\\mu$ 的乘积关系。当 $T_{pre}\\gg T_{dec}$ 且 $\\lambda$ 波动大时，同卡部署必然出现“预填批次挤占解码 SM”的抖动；反之若 $T_{pre}$ 与 $T_{dec}$ 同量级，拆池只是把一次抢占换成一次 NVLink 传输，得不偿失。</p>\n<p>Agentic VLM 的典型请求形态恰好落在前者：一次任务里图像/截图/文档页作为视觉输入进入，ViT 编码与跨模态注意力构成一次全序列前向，视觉 token 数可达文本 token 的数倍；而随后的自回归解码往往只产出几十到几百个 token 的工具调用或短答复。视觉 token 数的分布是长尾的——多数请求是单张小图，少数请求是整页高分辨率文档或连续多帧截图，后者把预填池的队列深度瞬间抬高。这就是“预填长尾明显”的工程含义：均值不可怕，P99 才决定 SLO。</p>\n<p>长度分布还决定 KV 传输是否可被掩盖。视觉 KV 的字节量正比于视觉 token 数与层数、头数、精度，长尾请求的 KV 块在 NVLink 上占据的时延可能超过预填池一个节拍，此时传输从“被掩盖”变成“被等待”。因此负载配方的第一条筛选规则是：视觉 token 的 P99 与 KV 传输时延的乘积，必须仍小于预填池单批次节拍，否则拆池的收益被传输吃掉。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-22\">二十二 · 并发与批大小的两套独立刻度</h3>\n<p>拆池之后，两个池的批处理队列不再共享同一个批大小，而是各自按自己的瓶颈量纲扩缩：预填池按视觉 token 数扩缩，解码池按并发序列数扩缩。这不是实现细节，而是负载配方的核心——预填的批是“token 批”，解码的批是“序列批”，二者的最优批大小由不同资源约束决定。预填池受 SM 算力与 TMEM 容量约束，批越大单批摊薄越好，但批内最长视觉序列决定整批时延；解码池受 HBM 带宽与 KV 容量约束，批越大权重读取摊薄越好，但受 KV cache 显存上限封顶。</p>\n<p>配比公式给出两池 GPU 数的稳态解：</p>\n<div class=\"formula\">$$N_{pre}/N_{dec} = \\frac{T_{pre}\\cdot \\lambda}{T_{dec}\\cdot \\mu}$$</div>\n<p>它的读法是：预填侧需要的算力正比于“每个请求的预填时间 × 到达率”，解码侧需要的算力正比于“每个请求的解码时间 × 在飞并发”。当 $\\lambda$ 突增（agent 批量提交截图）而 $\\mu$ 不变时，$N_{pre}/N_{dec}$ 必须上调，否则预填池排队、解码池空转；当长尾视觉请求集中到达，$T_{pre}$ 的 P99 抬升，配比需要按 P99 而非均值计算，这正是容量规划模型必须在线化的原因。</p>\n<p>整机吞吐由短板决定：</p>\n<div class=\"formula\">$$\\text{整机吞吐} = \\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$$</div>\n<p>这条式子解释了为什么配比失配的代价是双向的：预填池过剩时，解码池成为瓶颈，多出来的预填 GPU 闲置；解码池过剩时，预填池排队，解码池的连续批处理队列被抽空，批大小掉到 1，HBM 带宽利用率骤降。工程上要盯的不是单池利用率，而是两池队列深度的比值是否稳定在配比附近。</p>\n<p>具体例子：一个 agent 工作流在短时间内提交 32 个带整页文档图像的请求，每个请求视觉 token 数为常规请求的数倍。若配比仍按均值设定，预填池队列深度迅速堆到数十，而解码池因拿不到 KV 而批大小跌至个位数；此时整机吞吐由预填侧决定，解码侧的 Blackwell 带宽优势完全浪费。把预填池临时扩容、解码池相应收缩后，两池队列深度回到同一量级，吞吐回到 $\\min$ 的均衡点。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-23\">二十三 · 负载不对时的三种塌陷</h3>\n<p>第一种塌陷是传输成为新瓶颈。视觉 token 极长时，KV 跨池传输占用 NVLink 带宽，预填池算力被传输等待拖住——预填池算完了却写不出去，SM 空转等 DMA。此时预填池的有效节拍不再是 $T_{pre}$，而是 $\\max(T_{pre}, S_{KV}/BW_{\\text{NVLink}})$，配比公式里的分子被悄悄放大，按原公式算出的 $N_{pre}$ 偏小，队列越排越长。判断信号是预填池的 SM 利用率与 NVLink 出向带宽同时打满，而解码池队列深度不升。</p>\n<p>第二种塌陷是配比失配的静态僵化。两池配比需在线调优，配比失配时一侧空闲另一侧排队；缺少在线容量规划模型时，整机吞吐会低于同卡部署——因为同卡部署至少不会出现“一半 GPU 等另一半”的结构性空转。这类失败在负载形态缓慢漂移时最隐蔽：白天以短视觉请求为主，夜间批量文档任务涌入，固定配比在切换窗口内两侧都不饱和。</p>\n<p>第三种塌陷是块表跨池同步的时序错误。预填池把 KV 按分页块经 NVLink 写入解码池 HBM，块表跨池同步；若同步延迟，解码池按过期映射 gather KV 会读到错误块或触发重算。重算的代价是双倍的：既浪费了预填池已经付出的 ViT 与跨模态注意力算力，又在解码池上重新引入预填计算，破坏“解码池只做自回归”的纯净性。工程上必须让块表更新与 KV 块落盘构成一个原子可见性边界，解码侧只在块表确认后才允许调度该序列。</p>\n<p>三种塌陷的共同特征是监控指标背离：单池利用率看起来正常，但整机吞吐上不去。因此负载配方的观测面必须包含 KV 传输时延、池间队列深度比、块表同步延迟三项，而不是只看 GPU 利用率。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-24\">二十四 · 用 SLO 反推负载配方</h3>\n<p>负载配方不是先验给定的，而是从 SLO 反推出来的。解码 P99 时延目标决定解码池的最大批大小与并发上限：批越大单 token 摊薄越好，但 P99 随批内序列数上升，二者在某个批大小处相交，交点就是解码池的批上限。预填侧的 SLO 通常不是时延而是吞吐——agent 工作流对首 token 时延有容忍度，但对整体任务完成时间敏感，因此预填池可以承受更深的队列，用更大的 token 批换取算力利用率。</p>\n<p>反推的顺序是：先由解码 P99 定 $\\mu$ 与解码批大小，再由 $\\lambda$ 与 $T_{pre}$ 的 P99 定 $N_{pre}/N_{dec}$，最后用 KV 传输时延校验预填节拍是否仍被 NVLink 掩盖。若校验不通过，说明该负载形态不适合拆池，或必须对视觉 token 做前置缩减——那属于其他条目的主题，此处只指出它是配比公式失效时的逃生口。</p>\n<p>具体机制上，预填池按视觉 token 数扩缩意味着扩缩容的粒度是 token 而非请求数：一个视觉 token 数极多的请求可能触发一次扩容，而十个短视觉请求可能不触发。这要求调度器在入队时就完成视觉 token 数预估（ViT 的 patch 数由分辨率决定，可在预处理阶段算出），把预估结果作为队列权重的输入，而不是等 ViT 跑完才知道真实开销。</p>\n<p>代价面：在线调优本身消耗控制面资源与迁移成本，配比调整往往意味着 KV 块表的重分布或序列迁移，频繁抖动会引入额外时延。因此配比调整需要滞回区间，避免在阈值附近反复横跳。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-25\">二十五 · 边界条件与工程判断</h3>\n<p>适用边界写得很清楚：预填长尾明显、NVLink 带宽充足的 NVL72 整机。规模上限受 KV 传输带宽与配比调优精度约束。翻译成工程判断：当视觉 token 的 P99 大到 KV 传输时延超过预填节拍时，拆池的收益曲线开始走平甚至反转；当集群规模小到两池各自只能分到个位数 GPU 时，配比的分辨率不足以匹配负载波动，拆池的结构性空转可能吃掉全部收益。</p>\n<p>另一个边界是负载的稳定性。分离式架构的收益来自“两池独立扩缩容”，而独立扩缩容的前提是负载在两个维度上可分离：视觉 token 数的波动与解码并发的波动不相关。若某个 agent 工作流的视觉输入长度与输出长度强相关（长文档进、长报告出），两池的队列深度会同向波动，配比公式的分子分母同时变化，独立扩缩容退化为同步扩缩容，拆池只剩传输开销。</p>\n<p>工程上落地这份负载配方，最小闭环是三件事：入队时的视觉 token 数预估、块表与 KV 块的原子可见性、以及按 P99 而非均值计算的配比控制器。三者缺一，1.6–2.2 倍的整机吞吐提升与解码 P99 时延下降 50% 就无法在真实负载上复现——这两个数字对应的是负载形态匹配、配比在线收敛、传输被带宽掩盖三者同时成立的情形，而不是架构本身的固有属性。</p>\n<p>最后落在具体机制上：配比控制器的输入应当是池间队列深度比与 KV 传输时延的滑动分位数，输出是两池 GPU 配比的调整量，调整步长受滞回区间约束；当传输时延分位数逼近预填节拍时，控制器应优先触发视觉 token 前置缩减而非继续扩容预填池，因为后者只会把更多算力投入到等待传输的空转里。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-26\">二十六 · 负载配方与失效边界：这套拆分在什么请求形态下才成立</h3>\n<p>分离式预填/解码不是普适加速器，它把整机吞吐押在两个池的节拍匹配上。适配的请求形态是“视觉预填长尾明显、解码段短而并发高”的 agent 在线服务：图像分辨率与视觉 token 数分布离散、单请求预填时延 $T_{pre}$ 远大于解码时延 $T_{dec}$，且到达率 $\\lambda$ 与解码并发 $\\mu$ 使配比公式 $N_{pre}/N_{dec} = T_{pre}\\cdot\\lambda / (T_{dec}\\cdot\\mu)$ 落在可调区间内。此时预填池按视觉 token 数扩缩、解码池按并发序列数扩缩，两池队列深度独立，NVL72 整机吞吐可提升 1.6–2.2 倍、解码 P99 下降 50%。反过来，若请求以短文本、低分辨率图为主，$T_{pre}$ 与 $T_{dec}$ 同量级，拆分的收益被 KV 跨池搬运的固定开销吃掉。</p>\n<p>失效的第一条是传输瓶颈。KV 按分页块经 NVLink/C2C 写入解码池 HBM，其代价必须被预填节拍掩盖，即 $S_{KV}/BW_{NVLink} &lt; T_{pre}$；视觉 token 极长时 $S_{KV}$ 线性膨胀，传输时延超过预填节拍，预填池算力被传输等待拖住，整机吞吐退化为 $\\min(\\text{Thr}_{pre},\\text{Thr}_{dec})$ 中被传输压低的那一侧。第二条是配比失配：$N_{pre}/N_{dec}$ 偏离上式时，一侧 GPU 空闲、另一侧排队，整机吞吐甚至低于同卡部署；缺少在线容量规划模型时，这种失配在长尾突增下会被放大。</p>\n<p>第三条是块表跨池同步的一致性代价。解码池按块表 gather 视觉 KV，若同步延迟，解码池会按过期映射读到错误块或触发重算，表现为输出错乱或隐性的重复预填，前者污染 SLO、后者把省下的算力又还回去。工程判断是：把 KV 传输时延与池间队列深度作为一等监控指标，配比调整以“传输时延 &lt; 预填节拍”为硬约束，视觉 token 分布的上尾决定预填池的扩缩容上限，而不是均值。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>拆分收益</th><th>主要代价</th></tr></thead><tbody><tr><td>长尾视觉、短解码、高并发</td><td>吞吐 1.6–2.2×，P99 −50%</td><td>配比调优与传输监控</td></tr><tr><td>短文本、低分辨率、低并发</td><td>接近零或为负</td><td>KV 搬运固定开销</td></tr><tr><td>极长视觉 token</td><td>被传输瓶颈抵消</td><td>NVLink 带宽成为新瓶颈</td></tr></tbody></table>\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-27\">二十七 · 硬件档位的切分原则：先分池，再谈卡型</h3>\n<p>部署配方的第一步不是选卡，而是确认“两池物理可分”。在 GB200/GB300 NVL72 里，一个机柜内的 72 颗 GPU 通过 NVLink 5 域互联，预填池与解码池可以落在同一 NVLink 域内的不同 tray 上，KV 传输走 NVLink；跨机柜或跨域时则退化到 C2C/IB 路径，带宽量级下降，KV 传输时延项 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 立刻从可被掩盖变成主导项。因此硬件档位的第一条判断是：预填池与解码池必须共处一个 NVLink 域，否则分离式部署的收益被传输吃掉。</p>\n<p>第二条判断是卡型异构。预填池吃的是 ViT 卷积/注意力与跨模态注意力的算力密度，对 tensor core 吞吐与 TMEM 容量敏感，B200 与 B300 的差异主要体现在可用的 FP4/FP8 算力档与 SM 数量；解码池吃的是 HBM 带宽与 KV 容量，对单卡 HBM 容量和带宽更敏感。工程上常见的档位组合是：预填池用高算力档卡并配较少卡数，解码池用大显存档卡并配较多卡数，因为解码池的并发序列数直接由 KV 容量除以每序列 KV 字节数决定。若两池混用同一档卡，配比调节的自由度只剩卡数，容量规划会变窄。</p>\n<p>第三条是功耗与散热边界。NVL72 整柜功耗预算固定，预填池瞬时功耗高、解码池持续功耗平稳，两池分池后可以把功耗预算按池分配，避免同卡部署时预填尖峰把解码的持续频率拉低。这一点在风冷改液冷的机柜里尤其明显：分池后每池的功耗曲线更可预测，频率墙的触发点从“混合负载尖峰”变成“单池稳态”，对 SLO 的抖动更友好。</p>\n<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{pre}}^{\\text{vis}} + \\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}} + T_{\\text{dec}},\\quad \\text{整机吞吐} = \\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$$</div>\n<p>这个式子决定了档位选择的取向：整机吞吐由两池中较慢的一侧决定，所以硬件档位不能让任何一池成为结构性瓶颈。举例：若预填池单请求视觉预填时延 $T_{\\text{pre}}$ 因卡型算力不足而偏大，即便解码池再快，整机吞吐也被 $\\text{Thr}_{\\text{pre}}$ 钉死；反之解码池 KV 容量不足导致并发 $\\mu$ 上不去，$\\text{Thr}_{\\text{dec}}$ 成为天花板。档位配置的目标是让两池的 $\\text{Thr}$ 尽量相等，而不是各自最强。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-28\">二十八 · 并行拓扑：预填池张量并行、解码池按 KV 切分</h3>\n<p>预填池的并行拓扑以张量并行（TP）为主。ViT 与跨模态注意力的一次全序列前向是计算密集型，TP 度提高能把单请求预填时延压下来，代价是每层 all-reduce 走 NVLink，通信量与 TP 度成正比。Blackwell 的 2-SM MMA 与 tcgen05 让单 SM 内的矩阵乘效率提升，TP 度不必拉到极大即可满足预填算力，工程上倾向把 TP 度控制在能覆盖单请求视觉 token 长度的最小档，把剩余卡留给解码池。</p>\n<p>解码池的并行拓扑则以 KV 切分为主：由于解码是逐 token 自回归、每步只读 KV 不重算，KV 可以按头或按层切到多卡，形成“KV 并行”，每卡只持有部分 KV 分片，解码时各卡算部分注意力再合并。这样解码池的并发序列数随卡数线性增长，而单步解码的通信量远小于 TP 的 all-reduce。对 agent 长尾场景，解码池的扩缩容按并发序列数进行，KV 并行让“加卡即加并发”成为直接映射。</p>\n<p>两池之间的拓扑接口是块表。预填池产出的 KV 按分页块写入解码池 HBM，块表跨池同步；解码池按块表 gather KV。块表同步若走控制面而非数据面，会引入额外跳数，工程上把块表放在两池共享的元数据服务里，写入 KV 块与更新块表做成同一个原子步骤，避免解码池按过期映射读到错误块或触发重算。这是分离式部署里最容易被忽视的拓扑细节：数据面走 NVLink，控制面走共享元数据，两者的一致性由原子写保证。</p>\n<table class=\"mini\"><thead><tr><th>池</th><th>并行方式</th><th>扩缩容依据</th><th>主要代价</th></tr></thead><tbody><tr><td>预填池</td><td>TP（2-SM MMA、tcgen05）</td><td>视觉 token 数</td><td>all-reduce 走 NVLink，TP 度越高通信越多</td></tr><tr><td>解码池</td><td>KV 并行（按头/层切分）</td><td>并发序列数</td><td>KV 分片 gather 与合并，HBM 容量决定并发上限</td></tr></tbody></table>\n<p>具体例子：一个 agent 请求带多张高分辨率截图，视觉 token 数很大，预填池需要较高 TP 度才能在可接受时延内完成 ViT 与跨模态注意力；同一时刻在线解码池有大量短序列在跑，解码池按 KV 并行扩到较多卡以撑并发。若两池共用同一批卡做同卡部署，预填的长尾会把解码的 SM 占满，解码 P99 时延被拉长；分池后预填池的 TP 通信与解码池的 KV gather 互不干扰，这是拓扑分离的直接收益。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-29\">二十九 · 量化方案：预填吃 FP8/NVFP4，解码保 KV 精度</h3>\n<p>量化方案要按池分开定，不能一套量化打通两池。预填池的 ViT 与跨模态注意力是计算密集，权重与激活走 FP8 甚至 NVFP4 能直接换到算力档位，tcgen05 的 MMA 对低精度有原生支持，量化后的预填时延下降直接反映在 $T_{\\text{pre}}^{\\text{vis}}$ 项上。但视觉编码对数值误差敏感，量化粒度要细：ViT 的 patch embedding 与跨模态注意力的 QKV 投影不宜做极低比特，工程上把这两处留在 FP8，其余线性层可下探到 NVFP4。</p>\n<p>解码池的量化重点是 KV cache。解码是显存带宽密集，KV 的比特宽度直接决定每序列 KV 字节数与可支撑并发数。KV 量化到 FP8 能把 KV 容量减半、带宽需求减半，但视觉 KV 是只读不重算的，量化误差会一次性固化并在整个解码过程中反复被读取，误差不会像文本 KV 那样被后续 token 稀释。因此视觉 KV 的量化要单独评估：可以按块做分组量化并保留少量高精度块（例如跨模态注意力输出层对应的块），用混合精度 KV 换取容量与精度的平衡。</p>\n<p>代价侧要算清楚：预填池量化到 NVFP4 换来的算力提升，若使 $T_{\\text{pre}}$ 下降，则配比 $N_{pre}/N_{dec}$ 可以往解码侧倾斜，整机吞吐上限由解码池决定；解码池 KV 量化到 FP8 使并发 $\\mu$ 翻倍，$\\text{Thr}_{\\text{dec}}$ 提升，但若视觉 KV 精度不足导致需要重算或校验，反而增加解码池的额外计算，抵消容量收益。量化方案的选择标准是：让两池的 $\\text{Thr}$ 在量化后仍然接近，而不是单池指标最优。</p>\n<div class=\"formula\">$$N_{pre}/N_{dec} = \\frac{T_{pre}\\cdot \\lambda}{T_{dec}\\cdot \\mu}$$</div>\n<p>这个配比式在量化后要重算：$T_{pre}$ 随预填量化下降，$\\mu$ 随 KV 量化上升，两者同时变化时配比的最优点会移动。工程上把量化方案与配比调节放在同一个在线调优回路里，量化变更后重新标定 $T_{pre}$ 与 $\\mu$，再调卡数配比，避免量化上线后配比失配导致一侧空闲另一侧排队。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-30\">三十 · KV 策略：分页块、只读标记与传输节拍</h3>\n<p>KV 策略的核心是“视觉 KV 只读不重算”。预填池产出的视觉 KV 在解码池被标记为只读，解码过程中不再触发 ViT 或跨模态注意力重算，这消除了同卡部署里预填与解码互相抢占 SM 的根源。分页块是跨池传输的单位：KV 按固定大小的块切分，块表记录每块的池内地址与解码池地址映射，传输按块流水进行，解码池可以在块到达后立即开始对应序列的解码，不必等整条序列的 KV 全部到位。</p>\n<p>传输节拍要与预填节拍对齐。KV 传输时延需小于预填节拍才能被 NVLink 带宽掩盖：预填池完成一条请求的 KV 产出后，传输时间若短于下一条请求的预填时间，传输就在后台完成，解码池感知不到等待。视觉 token 极长时，单条请求的 KV 字节数 $S_{\\text{KV}}$ 变大，传输时延 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 超过预填节拍，传输成为新瓶颈，预填池算力被传输等待拖住。此时 KV 策略要转向压缩传输：对视觉 KV 做块级量化后再传，或对长视觉序列做分块流水传输并把解码池的起始解码提前到首块到达时。</p>\n<p>代价侧：KV 跨池传输占用 NVLink 带宽，而 NVLink 同时承载预填池的 TP all-reduce 与解码池的 KV gather，带宽是共享资源。工程上要给 KV 传输划出带宽配额，避免长视觉请求的 KV 传输把 TP 通信挤到排队。显存侧，解码池的 KV 容量按并发序列数与每序列 KV 字节数分配，视觉 KV 只读意味着它不能被换出后重算，只能换出到更低层级存储或丢弃后重新预填，后者代价极高，所以解码池的 KV 容量规划要按峰值并发留余量。</p>\n<p>具体例子：一条带多帧视频的 agent 请求，视觉 token 数远超文本 token，$S_{\\text{KV}}$ 很大，传输时延超过预填节拍，此时若仍按整条序列传完再解码，解码池空等；改为分块流水后，解码池在首块到达即开始解码，传输与解码重叠，$T_{\\text{e2e}}$ 中的传输项被部分掩盖。这就是 KV 策略与传输节拍对齐的工程价值。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-31\">三十一 · 调度参数与可复现配置思路</h3>\n<p>调度参数分三组：预填池的批大小与视觉 token 预算、解码池的连续批处理并发上限、两池之间的队列深度阈值。预填池按视觉 token 数扩缩，批大小受单请求视觉 token 长度分布影响，长尾请求会拉长批内最长序列的预填时间，工程上把预填批按 token 预算而非请求数切分，避免一条超长视觉请求拖住整批。解码池按并发序列数扩缩，连续批处理的上限由 KV 容量除以每序列 KV 字节数决定，超过上限的请求在池间队列排队。</p>\n<p>队列深度阈值是配比调节的触发条件。监控 KV 传输时延与池间队列深度，当预填池队列持续增长而解码池队列为空，说明预填池算力不足，需要把卡从解码池划给预填池；反之解码池队列增长而预填池空闲，则反向划卡。调节要带滞回，避免队列深度抖动导致卡数反复迁移，迁移本身会打断在跑的序列。可复现的配置思路是：先固定量化方案与并行拓扑，标定单请求 $T_{pre}$ 与解码并发 $\\mu$，用配比式算出初始 $N_{pre}/N_{dec}$，再以队列深度与 KV 传输时延为反馈做小步调节。</p>\n<ul><li>预填池：TP 度按视觉 token 长度档位定，FP8 为主、线性层可下探 NVFP4，批按 token 预算切分。</li><li>解码池：KV 并行按头切分，KV 走 FP8 并对视觉 KV 做混合精度分组，并发上限由 KV 容量反推。</li><li>传输：KV 分页块流水，块表原子写，KV 传输带宽配额与 TP 通信隔离。</li><li>调度：两池独立连续批处理队列，队列深度阈值带滞回触发配比调节。</li></ul>\n<p>失败模式要写进配置里：视觉 token 极长时 KV 跨池传输成为瓶颈，预填池算力被传输等待拖住；两池配比失配时一侧空闲另一侧排队，缺少在线容量规划模型会导致整机吞吐低于同卡部署；块表跨池同步若延迟，解码池按过期映射 gather KV 会读到错误块或触发重算。这三条对应三组监控指标：KV 传输时延与带宽占用、两池队列深度与卡数配比、块表同步延迟与 gather 命中率。配置的可复现性来自这三组指标的可观测，而不是某一组固定参数值。</p>\n<p>最后落在工程判断上：分离式部署的配置不是一次性调参，而是一个以配比式为核心的闭环。量化与拓扑决定 $T_{pre}$ 与 $\\mu$ 的量级，调度参数决定两池队列的稳态深度，KV 策略决定传输项能否被掩盖。任何一项变更都要重新标定配比，否则整机吞吐会被 $\\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$ 里较慢的一侧钉死。判断配置是否成立的唯一标准是：在目标 SLO 下，两池的队列深度同时处于低位且 KV 传输时延小于预填节拍。</p>\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-32\">三十二 · 五条资源账：谁在抢谁</h3>\n<p>把视觉预填与文本解码拆到两个 GPU 池之后，系统代价并没有消失，只是从“同一张卡上 SM 与 HBM 互抢”变成了“跨池的五条资源账各自独立结算”。这五条账是：预填池的 SM 算力（ViT 与跨模态注意力的矩阵乘）、解码池的 HBM 带宽（逐 token 自回归每步都要把权重与 KV 读一遍）、两池之间的 NVLink/C2C 传输带宽、两池各自的 HBM 容量（KV 分页块落地）、以及整机功耗与散热预算。拆分的本质是把这五条账从“耦合”改成“可分别定价”，代价是新增了一条跨池传输账，并且这条账在视觉 token 极长时会反客为主。</p>\n<p>先看拆分前后的账目结构差异。同卡部署时，一个长尾视觉请求的预填会占满 SM 数十毫秒，期间解码 batch 里的其他序列只能等 SM 空出来，解码的 P99 直接被预填的尾部长短决定；同时预填的大矩阵乘把 HBM 带宽吃满，解码每步的权重读取被挤到排队。拆成两池后，解码池的 SM 只跑自回归，HBM 带宽只服务解码，P99 由解码池自身的并发与块表查找决定，不再受预填尾部污染。这就是给定事实里“解码 P99 时延下降 50%”的机制来源——不是解码变快了，是解码不再被别人的预填打断。</p>\n<p>但预填池这一侧的资源账变复杂了：它不仅要算 ViT 与跨模态注意力，还要把产出的 KV 按分页块写出去。写出的动作占用的是 NVLink 端口与预填池自身的 HBM 写带宽，而写出的节拍必须与预填的计算节拍对齐，否则预填池的算力会被“等传输”拖住。给定事实把这条失败模式写得很明确：视觉 token 极长时 KV 跨池传输占用 NVLink 带宽并成为新瓶颈，预填池算力被传输等待拖住。也就是说，拆分把瓶颈从“卡内互抢”搬到了“卡间传输”，前者可以靠调度缓解，后者只能靠带宽预算与配比来管理。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-33\">三十三 · 传输时延必须被预填节拍掩盖</h3>\n<p>跨池传输能不能“免费”，取决于一个简单的不等式：单请求的 KV 传输时延必须小于预填池处理下一个请求的节拍，这样传输才能被后续预填的计算完全掩盖。写成式子就是给定事实里的端到端分解：</p>\n<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{pre}}^{\\text{vis}} + \\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}} + T_{\\text{dec}},\\quad \\text{整机吞吐} = \\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$$</div>\n<p>其中 $S_{\\text{KV}}$ 是该请求视觉+文本 KV 的字节数，$BW_{\\text{NVLink}}$ 是两池之间可用的有效带宽。这个式子的工程含义是：端到端时延里有一项是纯传输项，它不产生任何计算，却实打实占着关键路径。当 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 远小于 $T_{\\text{pre}}^{\\text{vis}}$ 时，传输被预填流水掩盖，端到端近似等于两段计算之和；当视觉 token 数把 $S_{\\text{KV}}$ 推到与 $T_{\\text{pre}}^{\\text{vis}}$ 同量级时，传输项开始显形，端到端时延出现一个无法靠加 GPU 消除的常数项。</p>\n<p>第二个式子是吞吐的 min 结构：整机吞吐等于预填吞吐与解码吞吐的较小者。这解释了为什么配比失配的代价如此之高——只要一侧成为短板，另一侧的算力就完全浪费。给定事实里的失败模式“两池配比失配时一侧空闲另一侧排队，缺少在线容量规划模型会导致整机吞吐低于同卡部署”，正是 min 结构的直接后果：不是平均变差，是短板决定一切。</p>\n<p>具体例子：一个 agent 请求携带一张高分辨率截图，ViT 切出数千个视觉 token，跨模态注意力后产出的视觉 KV 体量远大于同请求的文本 KV。此时 $S_{\\text{KV}}$ 主要由视觉部分贡献，传输项在端到端里占比上升；如果预填池仍按“每个请求算完就立刻写”的朴素节拍工作，写操作与下一请求的 ViT 计算会在 NVLink 端口上排队，预填池的有效吞吐被传输节拍钉住。工程上的应对不是加大预填池，而是把 KV 写出做成与计算重叠的异步流水，并按分页块粒度做流控，让传输始终躲在计算后面。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-34\">三十四 · 配比公式与它的三个失效面</h3>\n<p>两池各放多少张 GPU，是这套架构唯一需要在线决策的容量参数。给定事实给出的配比关系是：</p>\n<div class=\"formula\">$$N_{pre}/N_{dec} = \\frac{T_{pre}\\cdot \\lambda}{T_{dec}\\cdot \\mu}$$</div>\n<p>读法是：预填侧需要的卡数正比于“单请求预填时延 × 到达率”（即单位时间需要完成的预填工作量），解码侧需要的卡数正比于“单请求解码时延 × 解码并发”（即单位时间需要维持的解码工作量）。这个式子的价值不在于精确，而在于它把配比从“拍脑袋”变成“可观测量的函数”：$\\lambda$ 来自入口队列，$\\mu$ 来自解码池的活跃序列数，$T_{pre}$ 与 $T_{dec}$ 可以从两池各自的批处理统计里滚动估计。</p>\n<p>它有三个失效面。第一，$T_{pre}$ 不是常数：视觉 token 数的分布是长尾的，agent 请求里既有纯文本轮次也有整页截图，$T_{pre}$ 的方差极大，用均值算配比会在长尾到来时低估预填侧需求。第二，$\\mu$ 受 SLO 约束而非受算力约束：解码池的并发上限往往由 P99 目标反推，而不是由 HBM 容量决定，因此 $N_{dec}$ 不能简单按“能塞多少序列”来算。第三，公式假设两池之间没有反馈：一旦传输项显形，$T_{pre}$ 的有效值会被传输等待拉长，公式右侧被低估，配比进一步偏向解码侧，形成“预填越堵越少给卡”的正反馈。</p>\n<p>工程判断：配比调优必须把 KV 传输时延作为 $T_{pre}$ 的一部分计入，并且用池间队列深度做前馈而不是等 P99 恶化再反馈。给定事实要求“监控 KV 传输时延与池间队列深度，动态调整两池 GPU 配比以匹配 SLO”，这两项监控指标正是为了在正反馈形成之前打断它。规模上去以后先崩的地方，往往不是单池算力不够，而是配比在长尾分布漂移时跟不上，导致 min 结构里的短板来回切换，整机吞吐在两个工作点之间震荡。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-35\">三十五 · 块表同步：一条容易被忽略的正确性代价</h3>\n<p>KV 按分页块跨池传输，意味着解码池持有的块表必须与预填池写出的块映射保持一致。给定事实把这条失败模式列为：块表跨池同步若延迟，解码池按过期映射 gather KV 会读到错误块或触发重算。这不是性能问题，是正确性问题，而它的代价同时体现在延迟与吞吐上——读到错误块意味着输出错误，触发重算意味着预填池的工作被重复做一遍，等于把拆分省下来的算力又还了回去。</p>\n<p>机制上，块表同步有两条路径：随 KV 数据一起走带内同步（每个分页块的写请求里携带映射更新），或走独立的带外控制通道。带内同步的优点是顺序天然一致，缺点是映射更新与数据写共享同一条 NVLink 通道，在传输项已经显形时进一步加重端口竞争；带外同步的优点是控制流不与数据流抢带宽，缺点是需要额外的顺序保证机制，否则会出现“数据到了、映射没到”的窗口。工程上通常选择带内同步加写完成确认，把“映射可见”绑定在“数据落地”之后，用一次往返换取确定性。</p>\n<p>代价量化：块表同步引入的额外往返在正常路径上被预填流水掩盖，不进入关键路径；但在预填池高负载、NVLink 端口排队时，这个往返会与 KV 数据写一起排队，把原本可以掩盖的传输项推到关键路径上。因此块表同步的开销不是固定常数，而是随端口利用率非线性上升的——这也是为什么监控项里必须包含“KV 传输时延”而不是只看“KV 传输字节数”。</p>\n<p>具体例子：解码池在连续批处理中为新到的序列 gather 视觉 KV，如果块表里该序列的视觉块映射还停留在“未写入”状态，解码池要么阻塞等待（拉长首 token 时延），要么按旧映射读到上一轮复用的块（输出污染）。两种结果都让拆分架构的收益打折，而后者更危险，因为它不表现为延迟而是表现为错误。因此块表同步的工程要求是“写后可见”而非“最终一致”。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-36\">三十六 · 规模上去以后，先崩的是带宽账而不是算力账</h3>\n<p>把 NVL72 整机的 GPU 数量往上堆，五条资源账的缩放速率并不相同。预填池的算力随卡数线性增长，解码池的 HBM 带宽随卡数线性增长，但两池之间的 NVLink 有效带宽不是无限可分的——它是整机拓扑里的一段共享资源，KV 传输与集合通信、其他池的流量共享同一批链路。给定事实的适用边界写得很清楚：规模上限受 KV 传输带宽与配比调优精度约束。这句话的工程翻译是：当整机规模扩大时，最先饱和的不是 SM，而是跨池链路的利用率。</p>\n<p>为什么会这样？因为 KV 传输量正比于“完成的预填请求数 × 每请求 KV 字节数”，而预填请求数正比于整机吞吐。也就是说，整机吞吐越高，跨池传输的绝对字节量越大，链路利用率随吞吐线性上升。当链路利用率接近饱和，传输项从“被掩盖”变成“显形”，$T_{pre}$ 的有效值上升，预填池吞吐下降，min 结构的短板切换到预填侧，整机吞吐被封顶。这就是规模上去以后的第一道墙：它不是某张卡算不动，而是跨池链路搬不动。</p>\n<p>第二道墙是配比调优精度。规模越大，两池的 GPU 数量越多，配比的调整粒度越粗（一次调整可能挪动数十张卡），而长尾视觉请求的到达是突发的。粗粒度配比遇上突发长尾，结果是调整总是滞后一个节拍，池间队列深度在“预填排队”与“解码空闲”之间来回摆。给定事实把这一现象描述为“配比失配时一侧空闲另一侧排队”，并指出缺少在线容量规划模型会导致整机吞吐低于同卡部署——注意这个比较对象：不是低于理想值，是低于不拆分的同卡部署。这说明拆分的收益是有条件的，条件就是配比精度跟得上负载漂移。</p>\n<p>第三道墙是功耗与散热。两池拆分后，预填池的 ViT 大矩阵乘与解码池的持续 HBM 读写让整机功耗分布更均匀，但也意味着没有“一侧空闲时另一侧可以借功耗预算”的余地——两池同时工作在较高功耗点上，整机功耗上限成为扩缩容的硬约束。给定事实没有给出具体功耗数字，但机制上可以判断：当配比向某一侧倾斜时，被缩减的那一侧释放的功耗预算并不能自动转移给另一侧，因为功耗预算是按整机机架结算的。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-37\">三十七 · 尾延迟的真实构成与工程落点</h3>\n<p>agent 场景的尾延迟不是单一来源，拆成两池后它被分解成三段可分别归因的部分：预填池的排队时延（由视觉 token 长尾与预填池配比决定）、KV 传输时延（由 $S_{\\text{KV}}$ 与链路利用率决定）、解码池的排队与逐 token 时延（由解码并发与块表查找决定）。给定事实给出的“解码 P99 时延下降 50%”对应的是第三段——解码池不再被预填打断，其 P99 由自身并发决定。但端到端 P99 不一定同比例下降，因为第一段与第二段在长尾请求上会补回来。</p>\n<p>工程落点是：尾延迟优化必须按段归因，而不是看端到端一个数。如果端到端 P99 恶化而解码池 P99 平稳，问题在预填排队或传输项；如果解码池 P99 自身恶化，问题在解码并发或块表 gather 路径。给定事实要求监控“KV 传输时延与池间队列深度”，正是为了把第二段与第一段从黑箱里拆出来。一个具体的判断规则：当池间队列深度在预填侧持续增长而解码侧队列为空，说明配比偏向解码侧，应把卡从解码池挪向预填池；反之亦然。这条规则不需要精确的容量模型，但需要两个队列深度的实时可见性。</p>\n<p>最后落在机制上：这套架构的稳定性不取决于单池多快，而取决于“传输项是否始终小于预填节拍”这个不等式是否在所有负载点上成立。工程上维持它的手段有三个——把 KV 写出做成与计算重叠的异步流水、把块表同步绑定在数据落地之后、把配比调整做成基于队列深度的前馈控制。三者任一缺失，规模上去以后先崩的都是同一处：跨池链路利用率饱和导致传输项显形，min 结构把整机吞吐钉在预填侧。</p>\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-38\">三十八 · 精度问题：跨池 KV 的数值一致性与块表语义</h3>\n<p>分离式预填/解码把一次前向拆成两段执行、两段显存、两套并行拓扑，精度风险不在单个算子，而在“同一份 KV 在两池之间被重新解释”。预填池在 tcgen05 上以 NVFP4/FP8 产出视觉 KV，写入分页块时做量化与打包；解码池按块表 gather 回来做自回归。若两侧对 KV 的量化尺度、块内偏移、padding 语义理解不一致，解码池读到的是“数值上近似、语义上错位”的块——表现为输出突然跑偏、重复、或视觉问答答非所问，而单池部署完全复现不出来。</p>\n<p>诊断的核心是把“数值误差”与“映射误差”分开。数值误差随 token 位置累积，通常表现为随解码步数单调劣化的困惑度漂移；映射误差是离散的，往往在某个块边界处突然跳变。工程上给每个 KV 块携带一个轻量指纹（块首若干元素的校验和 + 量化尺度 + 块内有效长度），解码池 gather 时比对指纹，不一致即标记该请求为可疑并旁路重算该块。伪代码思路：</p>\n<div class=\"formula\">$$\\text{suspect}(r)=\\bigvee_{b\\in \\text{blocks}(r)} \\big[\\text{fp}(b)\\neq \\text{fp}_{\\text{pre}}(b)\\big]\\ \\lor\\ \\big[\\text{scale}(b)\\notin \\mathcal{S}_{\\text{dec}}\\big]$$</div>\n<p>代价落在解码池：指纹比对是纯带宽操作，每块几十字节，相对 KV 主体可忽略；但一旦触发旁路重算，该请求的视觉预填要在解码池重跑一遍 ViT，等于把省下来的算力又吐回去，P99 直接劣化。因此指纹只用于“定位”，不用于“修复”——修复动作应是回滚到同卡部署或重放该请求，而不是在解码池重算。具体例子：一个 agent 请求携带 4 张高分辨率截图，视觉 token 数千，块表跨池同步滞后一个节拍，解码池按过期映射 gather 到上一请求的块，指纹比对立刻暴露，运维侧看到的是“该请求 P99 尖刺 + 输出异常”同时出现，这正是映射误差而非数值误差的特征。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-39\">三十九 · OOM：显存被谁吃掉，以及分页块的跨池账本</h3>\n<p>分离式部署的 OOM 与同卡部署不同：它不是“一张卡装不下”，而是“两池的显存账本对不上”。解码池的 HBM 里同时躺着三类东西——本池自回归的 KV、从预填池传入的视觉 KV、以及为跨池传输预留的接收缓冲。视觉 KV 标记只读不重算，意味着它一旦写入就不能被常规的块回收策略驱逐，否则解码池要么重算要么报错。视觉 token 极长时，只读块在解码池里单调累积，连续批处理队列的并发序列数一涨，显存就被这些“不可驱逐块”钉死。</p>\n<p>可用的账本约束是：解码池可容纳的并发序列数受限于只读块总量与可驱逐块总量之和，而只读块由预填池的产出节拍决定。设单请求视觉 KV 占 $M_v$、文本 KV 占 $M_t$、接收缓冲占 $M_b$，则解码池的并发上限近似为</p>\n<div class=\"formula\">$$N_{\\text{dec}}^{\\max}\\approx \\frac{HBM_{\\text{dec}}-M_{\\text{resident}}}{M_v+M_t+M_b}$$</div>\n<p>其中 $M_{\\text{resident}}$ 是框架与权重常驻部分。工程判断：OOM 的第一信号不是分配失败，而是解码池的块分配器进入“碎片化高水位”——可驱逐块被只读块切碎，明明总量够却分配不出连续分页块。监控应盯“只读块占比”与“最大可分配连续块数”两个指标，而不是只看显存利用率。具体例子：预填池按视觉 token 数扩缩，一波长尾请求涌入使视觉 KV 产出速率翻倍，解码池并发序列数未变但只读块占比从常态抬升到高位，块分配器开始拒绝新序列，表现为“吞吐没降但新请求排队”——这是典型的只读块挤压，处置是临时收紧解码池并发上限并触发预填池限流，而非扩容解码池。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-40\">四十 · 批抖动与路由不均：队列深度是唯一可信信号</h3>\n<p>两池独立扩缩容带来的新失败模式是批抖动：预填池的批大小按视觉 token 数组织，解码池按并发序列数组织，两者的节拍天然不同步。当预填池一个大批次集中产出 KV，解码池在极短时间内收到大量块写入，其连续批处理队列被瞬间填满又瞬间排空，SM 利用率出现锯齿；反之预填池空转时，解码池的 KV 供给断流，解码批次被迫缩小，单 token 分摊的权重读取带宽上升，解码变慢。这种抖动不会体现在平均吞吐上，只体现在 P99 与功耗的波动上。</p>\n<p>路由不均则是抖动的空间版本：请求按某种哈希进入预填池的某个实例，若哈希只看请求 ID 而不看视觉 token 数，少数实例扛着超长视觉序列，多数实例闲着。诊断口径应统一到“池间队列深度 + KV 传输时延”这一对信号上——队列深度反映配比是否失配，传输时延反映 NVLink 是否被长视觉 token 打满。配比失配的判据可直接用前文的配比公式反向检查：实测 $N_{pre}/N_{dec}$ 偏离 $\\frac{T_{pre}\\lambda}{T_{dec}\\mu}$ 超过一个节拍，就说明一侧在排队另一侧在空闲。具体例子：agent 流量在整点集中触发，到达率 $\\lambda$ 阶跃上升，预填池队列深度先涨、解码池队列深度后涨，若扩缩容只按各自队列深度独立触发，两池会交替过冲，整机吞吐反而低于同卡部署——这正是缺少在线容量规划模型时的典型表现。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-41\">四十一 · 尾延迟尖刺：KV 传输成为新瓶颈的识别</h3>\n<p>分离式部署把原本藏在单卡内部的 KV 写回，变成了跨池的 NVLink 传输，于是尾延迟尖刺有了新的来源。端到端时延里多了一项 $\\frac{S_{KV}}{BW_{NVLink}}$，当视觉 token 极长时 $S_{KV}$ 线性增长，而 NVLink 带宽是整机共享资源，多个预填实例同时向解码池写块时会互相争抢。尖刺的形态很有辨识度：预填池的 ViT 计算时间正常，但“KV 写出完成”的时间戳被拉长，预填池算力被传输等待拖住，表现为预填池 SM 利用率下降而队列深度上升——算力没被计算占用，而是被等待占用。</p>\n<p>识别方法是把预填请求的时延拆成计算段与传输段分别打点，看尖刺落在哪一段。若传输段尖刺与解码池的块写入速率同步，说明是 NVLink 争抢；若传输段平稳而解码段尖刺，说明是解码池块分配或只读块挤压。掩盖条件是 KV 传输时延小于预填节拍，一旦视觉 token 长度分布的长尾超过这个阈值，掩盖失效，尖刺直接进入端到端 P99。工程判断：不要用平均传输时延做告警，用“传输时延超过预填节拍的比例”做告警，因为平均值会被大量短视觉请求稀释。具体例子：一批带长视频帧的 agent 请求进入，单请求视觉 KV 体量远超常态，预填池按视觉 token 数扩缩容滞后于到达，多个实例同时写块，NVLink 被打满，解码池 P99 出现尖刺而同卡部署基线无此现象——这就是“传输成为新瓶颈”的确定性证据。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-42\">四十二 · 监控面与回滚：把回滚做成一次配比切换</h3>\n<p>监控面要覆盖四个维度且互相可交叉：池间队列深度（配比）、KV 传输时延与超节拍比例（带宽）、只读块占比与最大连续可分配块数（显存）、块指纹不一致率（精度）。四者要按请求维度关联，否则只能看到“系统变慢”而无法归因到具体失败模式。告警阈值应绑定 SLO 而非绝对数值：解码 P99 相对基线的劣化幅度、整机吞吐相对 $\\min(\\text{Thr}_{pre},\\text{Thr}_{dec})$ 的缺口，这两个是最终判据。</p>\n<p>回滚不是“关掉分离式部署”，而是分级降级。第一级是配比回滚：把 $N_{pre}/N_{dec}$ 拉回容量规划模型给出的稳态值，牺牲部分预填吞吐换解码 SLO；第二级是路由回滚：把长视觉 token 请求从分离式路径摘出，走同卡预填解码路径，避免它们打满 NVLink；第三级才是拓扑回滚：整池合并回同卡部署。分级的意义在于每一级都有明确的触发指标——指纹不一致率升高走第二级（映射问题不该靠调配比解决），传输超节拍比例升高走第二级（长视觉 token 是根因），队列深度长期偏离走第一级。回滚动作本身要走块表：跨池块表在切换时必须做一次全量对账，否则回滚后解码池仍按旧映射 gather。具体例子：指纹不一致率在某个预填实例上突增，运维按第二级把该实例的在途请求重放，同时把该实例摘出轮转，解码池 P99 在数个节拍内恢复，而整机吞吐只损失该实例对应的预填份额——这是把精度故障限制在单实例范围内的工程做法。</p>\n<p>最终落在一条工程判断上：分离式预填/解码的稳定性不取决于单点最优，而取决于“配比—带宽—只读块”三者的联合约束是否被在线持续校验；任何一个维度失守，整机吞吐都会跌回甚至低于同卡部署，因此监控与回滚必须按这三个维度分别设闸，而不是等端到端 SLO 报警后再事后归因。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-43\">四十三 · 失效边界：当NVLink与配比精度成为新瓶颈</h3>\n<p>这套分离方案并非普适。它的第一个硬边界是KV传输带宽：视觉token极长时，预填池产出的视觉KV体积膨胀，跨池写入解码池HBM的时延可能超过预填节拍，此时NVLink不再是“被掩盖”的配角，而成为整条链路的瓶颈，预填池算力被传输等待拖住，整机吞吐反而低于同卡部署。判断是否越界可用一个简单的不等式：KV传输时延须小于单请求预填时延，否则传输无法被预填流水掩盖。第二个边界是配比精度，池间配比按$$N_{pre}/N_{dec} = \\frac{T_{pre}\\cdot \\lambda}{T_{dec}\\cdot \\mu}$$在线求解，其中$T_{pre}$、$T_{dec}$随视觉token分布漂移，$\\lambda$与$\\mu$随流量波动，配比失配时一侧空闲、另一侧排队，整机吞吐被$\\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$卡死。缺少在线容量规划模型时，这种失配是常态而非例外。</p>\n<p>第三个失效模式更隐蔽：块表跨池同步。解码池按分页块gather视觉KV，若块表同步滞后于KV写入，解码池会按过期映射读到错误块，轻则触发重算、拉高P99，重则输出与图像内容错位。诊断上应把“块表版本号与KV块写入序号的一致性”作为独立指标，与KV传输时延、两池队列深度并列监控，而不是只看端到端时延。回滚路径也应据此分级：块表不一致优先冻结跨池写入、退回同卡预填解码；配比失配则先调$N_{pre}/N_{dec}$再考虑回滚。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>代价落点</th><th>处置</th></tr></thead><tbody><tr><td>KV传输瓶颈</td><td>传输时延 ≥ 预填节拍</td><td>预填池SM空转、NVLink饱和</td><td>限流长视觉请求或增解码侧带宽</td></tr><tr><td>配比失配</td><td>一侧队列深度持续为0、另一侧堆积</td><td>整机吞吐低于同卡基线</td><td>在线重解配比公式</td></tr><tr><td>块表滞后</td><td>版本号与写入序号偏离</td><td>重算、输出错位、P99尖刺</td><td>冻结跨池写入、回退同卡</td></tr></tbody></table>\n<p>工程判断上，这套方案适合预填长尾明显、NVLink带宽充足的NVL72整机；一旦视觉token分布尾部变厚或流量突发，先看传输时延与块表一致性，再看配比——顺序错了会把带宽问题误诊为容量问题，越扩容越糟。</p>\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-44\">四十四 · 选型的第一性问题：谁在抢谁的资源</h3>\n<p>同族算法之间的选择，不应从“哪个技术更新”出发，而应从资源冲突的形态出发。Agentic VLM 服务里，视觉预填吃的是 SM 的 FMA 与张量核占用，解码吃的是 HBM 带宽与 KV 读取延迟；两者在同一张 GPU 上共存时，抢占关系是非对称的——预填的长尾请求一旦进入执行队列，解码的逐 token 步进就被拉长，P99 直接劣化，而解码侧的空闲周期又无法被预填有效填充，因为预填的并行粒度是整段视觉 token，不是逐 token。判断是否需要分离式预填/解码，先量化三个量：视觉 token 数分布的长尾程度、单请求预填时延 $T_{pre}$ 与解码时延 $T_{dec}$ 的比值、以及池间 KV 传输时延与预填节拍的比值。前两个决定“分离有没有收益”，第三个决定“分离能不能被 NVLink 掩盖”。若视觉 token 分布接近均匀、$T_{pre}/T_{dec}$ 接近 1，同卡连续批处理已经能把两类工作揉进同一时间片，分离只会额外引入传输开销与配比调优负担。</p>\n<div class=\"formula\">$$T_{\\text{e2e}} = T_{\\text{pre}}^{\\text{vis}} + \\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}} + T_{\\text{dec}},\\quad \\text{整机吞吐} = \\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$$</div>\n<p>这条公式是选型的分水岭：分离式把 $T_{\\text{pre}}^{\\text{vis}}$ 与 $T_{\\text{dec}}$ 放到不同 GPU 上并行推进，代价是中间插入 $\\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}}$ 一项。只有当这一项小于预填节拍（即预填池产出一个请求的 KV 所需时间大于传输该 KV 所需时间）时，传输才真正被掩盖；否则传输成为新的串行段，整机吞吐由 $\\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$ 退化为被传输带宽卡住的更小值。视觉 token 极长的 agent 请求正是这一项的放大器：KV 体积随视觉 token 线性增长，而 NVLink 带宽是固定的。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-45\">四十五 · 同族算法对照：五种路线各自消除什么</h3>\n<p>与本篇同族的条目可以按“消除哪一类开销”排成一条谱：视觉缓存复用消除的是跨请求重复编码；预语言模型视觉剪枝与熵引导视觉剪枝消除的是进入 LLM 前的视觉 token 数量；近似误差引导压缩与逐层视觉 token 压缩消除的是中间层激活与 KV 体积；双阶段统一 token 缩减与 DUET-VLM 消除的是预填与解码两阶段的 token 总量；跨阶段自适应并行服务消除的是阶段间的资源错配；多模态自适应投机解码消除的是解码步数；ViTCoP 消除的是视觉与文本预填之间的调度空隙；本文的分离式预填/解码消除的是预填与解码在同一 GPU 上的 SM 与 HBM 带宽互抢。它们不是互斥的替代品，而是作用在不同层：token 缩减类改变的是“要传多少”，分离式改变的是“在哪里算”。</p>\n<table class=\"mini\"><thead><tr><th>路线</th><th>消除的开销</th><th>主要代价</th><th>与分离式的叠加关系</th></tr></thead><tbody>\n<tr><td>视觉缓存复用</td><td>重复 ViT 编码</td><td>缓存显存与失效判定</td><td>降低预填池负载，放大分离收益</td></tr>\n<tr><td>视觉剪枝 / 熵引导剪枝</td><td>进入 LLM 的视觉 token 数</td><td>精度损失与判定开销</td><td>直接缩小 $S_{\\text{KV}}$，缓解传输瓶颈</td></tr>\n<tr><td>逐层压缩 / 误差引导压缩</td><td>KV 体积与激活带宽</td><td>压缩算力与精度风险</td><td>缩小跨池传输量，与分离式强互补</td></tr>\n<tr><td>双阶段统一缩减 / DUET-VLM</td><td>两阶段 token 总量</td><td>两阶段协同调度复杂度</td><td>改变预填/解码时延比，影响配比</td></tr>\n<tr><td>跨阶段自适应并行</td><td>阶段间资源错配</td><td>在线决策开销</td><td>与分离式目标重叠，二选一为主</td></tr>\n<tr><td>自适应投机解码</td><td>解码步数</td><td>草稿模型显存与接受率波动</td><td>压缩 $T_{dec}$，改变 $N_{pre}/N_{dec}$</td></tr>\n<tr><td>ViTCoP 协同预填</td><td>视觉/文本预填调度空隙</td><td>协同调度逻辑</td><td>作用于预填池内部，与分离正交</td></tr>\n</tbody></table>\n<p>关键判断是：分离式与“缩减类”是乘法关系而非加法关系。缩减类把 $S_{\\text{KV}}$ 压小，直接削弱分离式最大的代价项；而分离式让缩减类算法的收益更容易兑现，因为预填池可以独立按视觉 token 数扩缩，不必为解码 SLO 留出余量。反之，若已经部署了强力的逐层压缩把 KV 压到很小，同卡部署的抢占问题也随之减轻，分离式的边际收益下降。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-46\">四十六 · 决策表：按负载形态与互联条件落位</h3>\n<p>把选型拆成四个可观测条件：视觉 token 长尾度、预填/解码时延比、NVLink 可用带宽与拓扑、以及 SLO 中 P99 与吞吐的相对权重。下表给出落位判断，每一行都对应一个可测量的输入，而不是定性偏好。</p>\n<table class=\"mini\"><thead><tr><th>条件组合</th><th>首选路线</th><th>理由与代价</th></tr></thead><tbody>\n<tr><td>视觉 token 长尾显著、$T_{pre}\\gg T_{dec}$、NVL72 内 NVLink 带宽充足</td><td>分离式预填/解码</td><td>互抢消除，整机吞吐提升 1.6–2.2 倍、解码 P99 下降 50%；代价是传输与配比调优</td></tr>\n<tr><td>视觉 token 长尾显著但 KV 体积巨大、传输时延超过预填节拍</td><td>先上逐层压缩或剪枝，再考虑分离</td><td>传输成为新瓶颈，必须先缩小 $S_{\\text{KV}}$</td></tr>\n<tr><td>请求重复图像比例高、视觉内容稳定</td><td>视觉缓存复用优先</td><td>直接砍掉重复 ViT 编码，预填池负载下降后再评估分离</td></tr>\n<tr><td>预填与解码时延比接近 1、批处理已能揉合</td><td>同卡连续批处理 + 跨阶段自适应并行</td><td>分离引入的传输与调优成本难以回收</td></tr>\n<tr><td>解码占主导、预填占比小</td><td>自适应投机解码</td><td>压缩 $T_{dec}$ 比拆分阶段更直接</td></tr>\n<tr><td>单机多卡但无高带宽池间互联</td><td>ViTCoP 协同预填或同卡方案</td><td>KV 跨池传输无法被掩盖，分离式退化</td></tr>\n</tbody></table>\n<p>一个具体例子：agent 工作流中每轮携带一张高分辨率截图，视觉 token 数分布呈重尾，少量请求的视觉 token 数远超中位数，而文本解码只有几十个 token。此时 $T_{pre}^{\\text{vis}}$ 主导端到端时延，同卡部署下这些长尾请求会把在线解码的 P99 拖长数倍；分离后预填池按视觉 token 数扩缩、解码池按并发序列数扩缩，长尾被隔离在预填池队列里，解码池的逐 token 步进不再被视觉前向打断。这正是 50% P99 下降的来源，而不是任何单点算子优化。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-47\">四十七 · 配比与容量：选型之后的第二个决策</h3>\n<p>选定分离式之后，真正决定成败的是两池 GPU 配比。配比失配时一侧空闲、另一侧排队，整机吞吐甚至低于同卡部署——这是失败模式里最隐蔽的一条。配比由到达率与两阶段服务时间共同决定：</p>\n<div class=\"formula\">$$N_{pre}/N_{dec} = \\frac{T_{pre}\\cdot \\lambda}{T_{dec}\\cdot \\mu}$$</div>\n<p>其中 $\\lambda$ 为请求到达率、$\\mu$ 为解码并发数。这个式子说明配比不是静态常数：agent 负载的 $\\lambda$ 随会话轮次波动，$T_{pre}$ 随视觉 token 数波动，$T_{dec}$ 随输出长度与投机解码接受率波动。因此选型必须连带选择“配比是否在线可调”。若框架支持按池间队列深度动态迁移 GPU 配额，分离式的适用面扩大；若配比只能离线设定，则只适合负载形态稳定的场景。工程判断是：把 KV 传输时延与两池队列深度作为一等监控指标，任一指标持续偏离预填节拍，就说明当前配比或拓扑已经不匹配，此时应回退到同卡方案或先上压缩类算法，而不是继续加大分离规模。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-48\">四十八 · 边界条件与回退路径</h3>\n<p>分离式的适用边界由两条硬约束划定：规模上限受 KV 传输带宽约束，调优精度受在线容量规划模型约束。前者是物理的——视觉 token 极长时 $S_{\\text{KV}}$ 增长使 $\\frac{S_{\\text{KV}}}{BW_{\\text{NVLink}}}$ 超过预填节拍，预填池算力被传输等待拖住，此时增加预填 GPU 不再提升吞吐；后者是控制的——块表跨池同步若延迟，解码池按过期映射 gather KV 会读到错误块或触发重算，表现为解码侧莫名的重算尖峰与 KV 命中率下降。诊断上，若观察到预填池 SM 利用率高但产出 KV 的速率不涨，或解码池出现周期性重算，应优先怀疑传输与块表同步，而非算力不足。</p>\n<p>回退路径应当预先写进部署配方：当传输时延/预填节拍比值超过阈值，回退到同卡连续批处理并启用 ViTCoP 式协同预填；当视觉 token 长尾消失，回退到跨阶段自适应并行以保留弹性；当解码成为主导瓶颈，把资源转向投机解码而非继续拆分阶段。选型的本质不是选一个最强算法，而是选一组在给定互联带宽、给定负载形态、给定 SLO 权重下代价可被掩盖的组合——分离式只有在 NVLink 能吞下 KV 传输、且缩减类算法已把 $S_{\\text{KV}}$ 控制在可传输范围时，才是正确的那一个。</p>\n\n<h3 id=\"alg-agentic-vlm-pd-disagg-sec-49\">四十九 · 同族选型的边界判据：预填解码分离何时赢、何时被反噬</h3>\n<p>把本方案放进同族算法谱系里，对照轴只有两条：预填与解码是否共享同一组 SM/HBM，以及 KV 是否需要跨设备搬运。同卡连续批处理（chunked prefill 交错）不搬 KV，代价是视觉预填的长尾直接落在解码关键路径上；投机解码不改预填/解码的物理归属，只在解码侧压缩步数，对视觉预填抢占 SM 毫无缓解；分离式部署（本方案）唯一新增的系统代价就是 KV 传输。因此选型判据可以写成一个可计算的比较式：只有当跨池搬运被 NVLink 带宽完全掩盖、且两池配比可调时，分离才严格优于同卡。掩盖条件即 $T_{\\text{KV}} = S_{\\text{KV}}/BW_{\\text{NVLink}} &lt; \\tau_{\\text{pre}}$，其中 $\\tau_{\\text{pre}}$ 是预填池产出下一个 KV 块的节拍；一旦视觉 token 数把 $S_{\\text{KV}}$ 推到使该不等式翻转，预填池的算力就被传输等待拖住，分离退化为“两个都慢的池”。这正是本方案最清晰的失效边界：视觉 token 极长（高分辨率切片、多图、视频帧序列）时，KV 体积随视觉 token 线性增长，NVLink 从“掩盖者”变成“新瓶颈”。</p>\n<p>第二个判据是配比可调性。容量规划式 $N_{pre}/N_{dec} = (T_{pre}\\cdot\\lambda)/(T_{dec}\\cdot\\mu)$ 只在到达率 $\\lambda$ 与解码并发 $\\mu$ 稳定时成立；agent 负载的视觉请求是长尾分布，$\\lambda$ 的方差大，静态配比必然在某些时段失配——一侧空闲、另一侧排队，整机吞吐反而低于同卡部署。所以选型时要问的不是“分离能不能提速”，而是“有没有在线监控 KV 传输时延与池间队列深度并据此调 $N_{pre}/N_{dec}$ 的闭环”。没有这个闭环，同卡 chunked prefill 是更稳的默认项。第三个判据是块表跨池同步的一致性：解码池按过期映射 gather KV 会读到错误块或触发重算，这类故障不体现在吞吐曲线上，只体现在正确性上，属于分离架构特有的隐性代价。</p>\n<table class=\"mini\"><thead><tr><th>候选</th><th>适用条件</th><th>主要代价</th><th>失效信号</th></tr></thead><tbody><tr><td>同卡 chunked prefill</td><td>视觉 token 中等、SLO 宽松、无跨池带宽预算</td><td>预填长尾拖慢解码 P99</td><td>解码队列被视觉请求顶住</td></tr><tr><td>投机解码</td><td>解码侧带宽受限、草稿模型可得</td><td>草稿开销与接受率波动</td><td>预填抢占未缓解</td></tr><tr><td>本方案（预填/解码分离）</td><td>预填长尾明显、NVLink 带宽充足、有配比闭环</td><td>KV 传输占带宽、配比调优、块表同步</td><td>$T_{\\text{KV}}&gt;\\tau_{\\text{pre}}$ 或单侧排队</td></tr></tbody></table>\n<p>把三条判据落到工程判断上：先测 $S_{\\text{KV}}/BW_{\\text{NVLink}}$ 与 $\\tau_{\\text{pre}}$ 的比值，若余量不足一个数量级，就不要把长视觉请求放进分离池，而是让它们在预填池内做分块预填、只把文本 KV 下沉；再确认监控面能同时看到 KV 传输时延、两池队列深度和块表同步延迟三个量，缺一个就不要开自动配比；最后用整机吞吐 $\\min(\\text{Thr}_{\\text{pre}},\\text{Thr}_{\\text{dec}})$ 作为唯一验收指标，因为分离架构的收益全部来自这个 min 被抬高，任何单池指标的好看都不构成选型理由。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 视觉编码器低延迟推理</td></tr><tr><td>解决什么</td><td>多模态agent服务中视觉预填（ViT+跨模态注意力）是计算密集且长尾，解码是显存带宽密集且短，二者在同一GPU上互相…</td></tr><tr><td>一句话机制</td><td>把视觉预填与文本解码拆到不同GPU池：预填池跑ViT与跨模态注意力生成视觉KV，经NVLink/C2C把KV传到解码池…</td></tr><tr><td>代价与失效</td><td>KV跨池传输占用NVLink带宽，视觉token极长时传输成为新瓶颈；两池配比需在线调优，配比失配时一侧空闲另一侧排队，需容量规划模型支撑</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-agentic-vlm-pd-disagg · 共 8 个片段</p>\n";break;}}})();
